window.harnessChunks["rows-856b619e2e7a7cb1.js"]=["<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-09-17T20:13:36+03:00\"><th scope=\"row\"><a href=\"https://github.com/langchain-ai/deepagents\" target=\"_blank\" rel=\"noopener\">Deep Agents</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-17\">2026-09-17</time></td><td class=\"review-ref\"><a href=\"https://github.com/langchain-ai/deepagents/tree/f86b4e9abef7620b63a7258bc9fab0ccd83de8a4\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision f86b4e9abef7620b63a7258bc9fab0ccd83de8a4\">f86b4e9 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: the primary and delegated agents autonomously perform model/tool work.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: concurrent async tasks, isolation and lifecycle APIs establish multiple S1 units but no specific first-party inter-S1 interference/oscillation plus attenuation relation. Start/update/cancel/list are hierarchical current-control rights, not mutual-adjustment evidence by themselves.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: the main agent has a live view of its tracked background commitments and model-facing authority to start, inspect, redirect/interupt, cancel and list those commitments. The decisive intervention is chosen by the autonomous main agent; SDK/LangGraph machinery transports and enforces it. This closes a current whole-subagent-set regulation loop without a developer having to supply another control actor.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: a separate rubric grader challenges a candidate completion and can independently gather read-only evidence through the first-party dcode wiring. needsrevision findings are returned into the primary loop and cause further work. This is materially complementary access plus autonomous audit judgment and feedback closure, rather than ordinary inline QA.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: rubric iteration, memory, skills and task updates concern present execution/quality. No separate prospective environment-facing loop that changes future organizational capability/strategy was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: HITL/interrupton, rubrics and runtime options can gate operational actions or define acceptance criteria, but they do not establish identity/ultimate-policy closure. Generic human interruption is therefore not S5=P.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/3c76cda1b3c51a33c84eeaa45ac3c296a54f8c3c/assessments/deepagents.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 3c76cda1b3c51a33c84eeaa45ac3c296a54f8c3c\">3c76cda &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-09-17T20:13:36+03:00\"><th scope=\"row\"><a href=\"https://github.com/QwenLM/qwen-code\" target=\"_blank\" rel=\"noopener\">Qwen Code</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-17\">2026-09-17</time></td><td class=\"review-ref\"><a href=\"https://github.com/QwenLM/qwen-code/tree/3ac6fe65e81c84897c02d22abd3dc91d1e567d5f\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 3ac6fe65e81c84897c02d22abd3dc91d1e567d5f\">3ac6fe6 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: coding agents autonomously perform tool-using work inside their assigned scope.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: multiple S1 teammates share task ownership and messages. Atomic claiming prevents duplicate task ownership, priority delivery changes subsequent teammate behavior, and bounded pending-message queues attenuate a concrete flood/interference mode. Agents choose task/message actions while TeamManager provides deterministic enforcement and feedback.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: the team leader is an autonomous current-control actor over the team. It can create/direct teammates and invoke a leader-only shutdown that removes a teammate from participation and releases its task commitment; TeamManager supplies the whole-team state/lifecycle substrate and closes the intervention. Separately, Qwen Code&#39;s interactive approval mode can require the parent user to allow/deny these ask-classified team-control actions before execution, establishing a distinct parent-governed S3 mode.\">A(P)</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: no distinct complementary audit actor/path with materially different access to operational reality and findings returned into current control was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: no separate outside-and-future adaptation loop was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: approval modes and team-action permissions govern operational interventions. They do not establish a first-party identity/ultimate-policy question and legitimate ultimate-authority loop, so the previous generic S5=P interpretation is removed.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/3c76cda1b3c51a33c84eeaa45ac3c296a54f8c3c/assessments/qwen-code.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 3c76cda1b3c51a33c84eeaa45ac3c296a54f8c3c\">3c76cda &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-09-16T23:24:44+03:00\"><th scope=\"row\"><a href=\"https://github.com/microsoft/agent-framework\" target=\"_blank\" rel=\"noopener\">Microsoft Agent Framework</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-16\">2026-09-16</time></td><td class=\"review-ref\"><a href=\"https://github.com/microsoft/agent-framework/tree/1cd06c5a2058a172eebadf5d9d7c3fa45c519520\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 1cd06c5a2058a172eebadf5d9d7c3fa45c519520\">1cd06c5 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: specialist agents autonomously perform bounded tool/model work and return operational outcomes.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: the Magentic manager actively detects loop/stall/no-progress conditions and changes team execution to restore convergence. This is agent-owned regulation of instability among operational units, not static graph topology.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: the default Magentic manager owns a whole-team current-state ledger of facts/plan/progress, chooses who acts next, and has reset/replan authority over current commitments, establishing an autonomous S3 mode. The first-party plan-review option establishes a second parent-governed mode over the same S3 function: before a plan executes, a human sees the current progress ledger and proposed whole-team plan and may approve it or require revision; revision is returned to the manager, which replans before work continues. This is materially different from participant tool-call approval because it controls the team&#39;s current plan itself.\">A(P)</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: the same manager that regulates current work observes progress; no organizationally distinct complementary audit channel with independent access/authority was established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: replanning responds to current execution failure. The reviewed implementation does not establish a separate prospective external-environment intelligence function that adapts future system capability/strategy.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: goals, participants, instructions and orchestration policy remain application-defined. Human signoff on a current Magentic plan is S3 current-control authority, not by itself ultimate organizational identity or policy closure.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/9ee1ea7472777767928c8b2ab035e0948a0467e9/assessments/microsoft-agent-framework.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 9ee1ea7472777767928c8b2ab035e0948a0467e9\">9ee1ea7 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-09-20T21:45:19+03:00\"><th scope=\"row\"><a href=\"https://github.com/matiasrodlo/veritas\" target=\"_blank\" rel=\"noopener\">Veritas</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-20\">2026-09-20</time></td><td class=\"review-ref\"><a href=\"https://github.com/matiasrodlo/veritas/tree/f366432381834dee8ecb17bcbc2bad3e6232ff0b\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision f366432381834dee8ecb17bcbc2bad3e6232ff0b\">f366432 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: generate, debug, execute, compare, and refine experiment implementations to gather scientific evidence for the loaded research idea. - Disturbance / variety regulated: code/runtime failures, inadequate implementations, hyperparameter uncertainty, poor metrics, scaling choices, and uncertainty about which experimental change best tests the hypothesis. - Decisive decision or feedback right: choose candidate implementation changes and subsequent experiment actions in response to execution errors, journal history, metrics, and stage goals. - Decision owner: the model-driven tree-search research agent (ParallelAgent/candidate-generation path). - Supporting / enforcement mechanisms: isolated interpreter, execution timeout/resource controls, journals/tree nodes, named metrics and provenance, multi-seed evaluation, artifacts/plots, search configuration, and checkpoints. - Closure path: generated code is executed; errors/metrics/artifacts return into the search journal and prompts; subsequent nodes implement revisions or alternative experiments until stage criteria/limits are reached. - Boundary reachability: the tree-search agent and interpreter are the core path invoked by launchscientistbfts.py; no external agent harness supplies the experiment loop. - Why this is / is not agent-owned: deterministic execution and metric parsing constrain/measure candidates, but the model-driven agent chooses substantive implementation and experiment changes. - Evidence: README search description, tree-search runner, AgentManager agent creation. - Basis: explicit + structural. - Confidence: high. - Caveats: parallel candidates/tree branches are alternative attempts inside the operational research process; their plurality is not itself evidence of S2.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material S2-specific inter-S1 coordination loop is established at the declared recursion. - Disturbance / variety regulated: not established. - Decisive decision or feedback right: not established. - Decision owner: not applicable. - Supporting / enforcement mechanisms: worker isolation, process/resource limits, stage sequencing, shared journals, and candidate ranking prevent contamination or structure search but do not evidence a concrete interference/oscillation among distinct cooperating S1 units. - Closure path: not established. - Why this is / is not agent-owned: concurrent or branching experiment attempts are not automatically separate operational units requiring S2; they are candidate searches for one S1 research outcome. - Evidence: README execution/isolation description, experiment runner. - Basis: structural negative finding. - Confidence: high. - Caveats: a future multi-researcher mode would require a distinct S1 mapping and explicit interference/attenuation witness.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A - Function: maintain current evidence about the whole active research search/stage and decide completion, next-substage focus, and progression of the experiment program. - Disturbance / variety regulated: stagnating search, unmet stage success criteria, unresolved implementation issues, insufficient improvement, under-scaled experiments, and uncertainty about the most useful next search focus. - Decisive decision or feedback right: decide whether the current stage/substage is complete and generate specific goals/focus for the next substage from current progress/issues/metrics. - Decision owner: AgentManager&#39;s model-driven feedback/evaluation path for discretionary completion/focus judgments, operating within deterministic minimum/max/adaptive-stopping constraints. - Supporting / enforcement mechanisms: full stage journal, best-node selection, success-criteria checks, improvement counters, deterministic stopping rules, stage history, checkpoints, and stage lifecycle code. - Closure path: current journal metrics/issues/recent changes are summarized into the feedback model; the resulting completion decision or generated substage goals alter stage lifecycle and the prompt/goals used by the next research agent. - Boundary reachability: AgentManager is the standard controller instantiated by the main tree-search runner, and its feedback model/path is configured as part of normal experiment execution. - Why this is / is not agent-owned: fixed timeouts/max-iterations and metric checks are enforcement. S3 credit comes from the additional model-driven current-control judgment that interprets current whole-stage evidence and creates the next research focus. - Whole-system current view: active stage journal, all attempts in that stage, good/buggy nodes, best metric/node, success-criteria progress, current issues/recent changes, stage history, and prior-stage best implementation when relevant. - Current-control decision scope: stage completion, continuation versus progression, and specific next-substage research goals/focus that determine subsequent resource/effort commitment within the run. - Evidence: AgentManager completion logic, next-substage goal generation, standard runner. - Basis: structural. - Confidence: high. - Caveats: not every AgentManager decision is autonomous: many limits/checks are deterministic. The positive state depends specifically on the model-driven completion and next-focus decisions wired into current operation.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no material operationally closed complementary-audit loop is established in the reviewed full-run path. - Disturbance / variety regulated: not established at S3 scope. - Decisive decision or feedback right: no independent audit right with corrective return is established. - Decision owner: not applicable. - Supporting / enforcement mechanisms: metric provenance, multi-seed checks, plot/VLM checks, zero-data abort, and final automated paper review provide validation/review surfaces. - Closure path: the final review is written after the experiment search and paper generation, but the reviewed launcher does not feed its findings back into AgentManager, write-up, or experiments for corrective operation. - Why this is / is not agent-owned: performreview is a separate review action by name, but S3 requires complementary audit plus findings-to-control closure. Post-hoc persisted review without return is insufficient. - Evidence: launcher review path, README output including reviewtext.txt. - Basis: structural negative finding. - Confidence: high. - Caveats: internal VLM/metric validation is part of ordinary search acceptance/current control, while the separate final review lacks corrective return.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S4 / adaptation: - State: A - Function: in the supported idea-generation mode, sense external scientific literature, reflect on novelty/feasibility, and produce a future experiment program that the standard research run can execute. - Disturbance / variety regulated: risk that a proposed research direction duplicates existing work, misses relevant prior findings, or lacks a feasible/meaningful experimental plan. - Decisive decision or feedback right: choose/refine/finalize the research proposal after incorporating Semantic Scholar retrieval into repeated idea reflection. - Decision owner: the model-driven idea-generation agent. - Supporting / enforcement mechanisms: first-party Semantic Scholar tool, multi-round reflection history, prior-idea archive, structured FinalizeIdea schema, and instruction requiring at least one literature search before finalization. - Closure path: external literature results enter the reflection loop; the finalized idea includes related work, hypothesis, experiments, and risk factors; the resulting JSON is directly consumable by launchscientistbfts.py, where it determines subsequent staged experimental capability/work. - Boundary reachability: README documents performideationtempfree.py as the first-party way to create an ideas file from a short workshop brief; its output is the same schema consumed by the standard launcher. - Why this is / is not agent-owned: the literature tool retrieves external distinctions, but the model-driven ideation loop owns proposal selection/refinement; the experiment launcher then operationalizes the returned option. - External distinction: retrieved Semantic Scholar prior work and related-work information outside the current Veritas run. - Future / prospective distinction: novelty, feasibility, and which hypothesis/experimental direction should be pursued in later stages. - Adaptation option generated: finalized research idea containing hypothesis, related work, experiment plan, and risks/limitations. - Path back into current capability / S3: the idea JSON becomes the launcher&#39;s task description; AgentManager derives stage work from its experiment plan and executes the resulting research program. - Evidence: idea-generation tool and required literature search, README documented idea generation, launcher idea loading. - Basis: explicit + structural. - Confidence: high. - Caveats: the internal creativeresearch stage and reuse of previous experiment results are not the basis for S4. Credit depends on the distinct first-party external-literature → future idea → launched experiment closure.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no material identity/ultimate-policy authority loop is established at the declared research-run recursion. - Disturbance / variety regulated: not established at S5 scope. - Decisive decision or feedback right: not established. - Decision owner: not applicable. - Supporting / enforcement mechanisms: user/workshop idea, structured idea schema, stage goals, configuration, model choices, resource limits, and review/write-up settings constrain operation. - Closure path: no identity/ultimate-policy issue is shown reaching a legitimate authority and returning as a binding decision to subsequent operation. - Why this is / is not agent-owned: idea generation chooses the scientific direction to pursue, which is credited as S4; it does not evidence authority to redefine the system&#39;s ultimate identity/governance policy at runtime. - Evidence: idea schema and launcher, AgentManager stage contract. - Basis: structural negative finding. - Confidence: high. - Caveats: human selection of the input idea/configuration is not automatically parent-governed S5.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/c9da28372ac35ff5d8bc9a74679a6987a5d451df/assessments/veritas.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit c9da28372ac35ff5d8bc9a74679a6987a5d451df\">c9da283 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-09-20T21:45:19+03:00\"><th scope=\"row\"><a href=\"https://github.com/SakanaAI/AI-Scientist-v2\" target=\"_blank\" rel=\"noopener\">The AI Scientist-v2</a><small>2025</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-20\">2026-09-20</time></td><td class=\"review-ref\"><a href=\"https://github.com/SakanaAI/AI-Scientist-v2/tree/96bd51617cfdbb494a9fc283af00fe090edfae48\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 96bd51617cfdbb494a9fc283af00fe090edfae48\">96bd516 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: autonomously perform executable ML research experiments through model-driven proposal/code changes, execution and feedback-guided search. - Disturbance / variety regulated: implementation failures, changing metrics/plots, alternative model/data choices, debugging needs and experimental outcomes across tree-search nodes. - Decisive decision or feedback right: choose concrete experiment/code changes and search-node actions based on current task description, parent node/history and execution feedback. - Decision owner: first-party parallel experiment/search agents instantiated by AgentManager. - Supporting / enforcement mechanisms: journals/nodes, experiment executor callbacks, workspace isolation/state, stage-specific task descriptions, search budgets and GPU/process management. - Closure path: research-stage goal/current node -&gt; agent proposes implementation/experiment -&gt; runtime executes it -&gt; metrics/errors/plots are recorded in journal state -&gt; agent/search policy chooses subsequent node/action. - Boundary reachability: the tree-search agents are created and run by the shipped AgentManager used directly by launchscientistbfts.py. - Why this is / is not agent-owned: schedulers/GPU management enforce execution resources, but the context-sensitive experimental action is selected by model-driven agents. - Evidence: README.md, agentmanager.py, parallelagent.py. - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material agent-owned S2 coordination path is established among the parallel S1 search workers. - Disturbance / variety regulated: workers share finite execution resources and contribute nodes to experiment search, but no agent-owned interference/oscillation detector and attenuation relation is established. - Decisive decision or feedback right: none established for S2. - Decision owner: none established for S2. - Supporting / enforcement mechanisms: parallel worker scheduling, GPU manager/allocation, journals and tree-search selection. - Closure path: resource/scheduling code assigns/releases execution capacity and search code selects nodes; this is deterministic orchestration rather than an S2 conflict-regulation conversation. - Why this is / is not agent-owned: worker plurality and GPU allocation are not promoted to S2 without an agent-owned response to a concrete inter-S1 disturbance. - Evidence: parallelagent.py, agentmanager.py. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A - Function: maintain a whole-experiment current view and adaptively control stage completion, continuation and next experimental focus on behalf of the research run. - Disturbance / variety regulated: incomplete or unstable implementations, insufficient dataset coverage, weak progress, missing stage criteria, changing best-node evidence and current experimental issues. - Decisive decision or feedback right: judge whether the current sub-stage/stage is complete and generate measurable next sub-stage goals/focus from current experiment evidence; advance or continue the staged research program accordingly. - Decision owner: the model-driven feedback/control queries executed by the first-party AgentManager over its whole current stage/journal state. - Supporting / enforcement mechanisms: stage/journal state, best-node selection, VLM plot feedback, structured completion function schemas, hard bounds/fallback rules, checkpointing and stage-transition machinery. - Closure path: current journals/best node/metrics/plot feedback -&gt; manager control query judges completion or identifies missing criteria -&gt; manager continues current stage or creates a new focused sub-stage/main stage -&gt; subsequent agents receive the revised stage goals and operate under them. - Boundary reachability: AgentManager is instantiated by the standard BFTS experiment path and its run() loop directly creates worker agents and applies the completion/focus decisions. - Why this is / is not agent-owned: fixed stage ordering and max-iteration bounds are deterministic support, but the materially adaptive completion/focus judgments are model queries that change subsequent whole-run experiment commitments. - Whole-system current view: current stage, all stage journals/history, best implementation, success counts/metrics, VLM feedback, tested datasets and current issues/progress at the declared experiment-run recursion. - Current-control decision scope: whether to continue/complete the current stage and what concrete goals/focus the next sub-stage should impose on all subsequent experiment workers. - Evidence: agentmanager.py, performexperimentsbftswithagentmanager.py. - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no material complementary audit loop returning sufficiently independent findings into the S3 current-control path is established at the reviewed revision. - Disturbance / variety regulated: VLM plot analysis, multi-seed evaluation and final paper review provide evaluation signals, but their roles do not establish a separate operational audit channel with corrective return to S3. - Decisive decision or feedback right: none established for S3. - Decision owner: none established for S3. - Supporting / enforcement mechanisms: plot/VLM feedback, multi-seed evaluation, LLM text review and image/caption/reference review. - Closure path: VLM/metric feedback is consumed as part of ordinary manager evaluation; final paper reviews are written to files after write-up and are not returned into a correction/re-control loop. - Why this is / is not agent-owned: evaluator agents/models exist, but evaluation naming or separate inference alone is insufficient without a complementary independence-and-corrective-return closure. - Evidence: agentmanager.py, launchscientistbfts.py. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S4 / adaptation: - State: A - Function: sense external literature and prospective scientific opportunity, generate/refine a future research proposal, and return that option into current experiment execution. - Disturbance / variety regulated: prior literature may make ideas non-novel; alternative hypotheses/experiments may differ in feasibility, impact and relation to existing work. - Decisive decision or feedback right: choose search queries, incorporate retrieved literature into reflection, and finalize a structured future proposal/hypothesis/experiment plan. - Decision owner: first-party ideation LLM agent using the shipped Semantic Scholar tool loop. - Supporting / enforcement mechanisms: SemanticScholarSearchTool, action/tool protocol, reflection loop, structured FinalizeIdea schema and JSON handoff to launcher. - Closure path: workshop/topic description -&gt; ideation agent searches external literature -&gt; retrieved results alter reflection/proposal -&gt; agent finalizes structured idea -&gt; launchscientistbfts.py consumes that idea and executes the experiment program. - Boundary reachability: performideationtempfree.py is the documented first step for generating the JSON consumed by the standard experiment launcher. - Why this is / is not agent-owned: the search tool supplies evidence, but the prospective research-option synthesis and finalization are agent decisions. - External distinction: Semantic Scholar literature and related-work evidence. - Future / prospective distinction: novelty, feasibility, risks and which hypothesis/experiments should be pursued next. - Adaptation option generated: structured research proposal containing hypothesis, related work, experiments and limitations. - Path back into current capability / S3: generated idea JSON becomes the task description for AgentManager and its experiment stages. - Evidence: performideationtempfree.py, README.md, launchscientistbfts.py. - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no first-party identity/ultimate-policy closure is established. - Disturbance / variety regulated: workshop/topic descriptions, stage goals, risk-factor prompts, model choices and BFTS configuration constrain research, but they do not form an identity-level ultimate-authority loop. - Decisive decision or feedback right: none established for S5. - Decision owner: none established for S5. - Supporting / enforcement mechanisms: workshop description, proposal schema, hard-coded main-stage goals, YAML search configuration and CLI arguments. - Closure path: configuration/prompt policy directly constrains the run; no identity/ultimate-policy issue is escalated to an authoritative actor and returned as governing policy. - Why this is / is not agent-owned: the agent manager can adapt current experimental focus, but it is not given authority to redefine the system&#39;s identity or ultimate research policy. - Evidence: agentmanager.py, performideationtempfree.py. - Basis: structural -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/c9da28372ac35ff5d8bc9a74679a6987a5d451df/assessments/ai-scientist-v2.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit c9da28372ac35ff5d8bc9a74679a6987a5d451df\">c9da283 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-09-20T21:45:19+03:00\"><th scope=\"row\"><a href=\"https://github.com/SakanaAI/AI-Scientist\" target=\"_blank\" rel=\"noopener\">The AI Scientist</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-20\">2026-09-20</time></td><td class=\"review-ref\"><a href=\"https://github.com/SakanaAI/AI-Scientist/tree/1de1dbc1f4ee2c5f61e9c94348d55eb51d7fa2eb\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 1de1dbc1f4ee2c5f61e9c94348d55eb51d7fa2eb\">1de1dbc &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: autonomously implement and execute research experiments and produce the resulting scientific artifacts within a maintained experiment template. - Disturbance / variety regulated: code/runtime errors, differing experimental ideas, metric outcomes, plotting/write-up needs and project-file state. - Decisive decision or feedback right: choose concrete experiment/code edits and subsequent actions based on the idea, baseline state and observed execution/results. - Decision owner: the active model-driven Aider coding/experiment agent used by the first-party experiment loop. - Supporting / enforcement mechanisms: copied per-idea workspace, baseline results, performexperiments, Aider file editing, process execution, notes/logs and bounded experiment flow. - Closure path: idea/baseline/workspace -&gt; agent edits experiment implementation -&gt; code executes -&gt; result/error evidence returns -&gt; agent chooses further experiment edits or completion. - Boundary reachability: the loop is invoked by the documented launchscientist.py entrypoint for every novel idea in a standard paper-generation run. - Why this is / is not agent-owned: Python launcher logic enforces sequencing, but the context-sensitive experiment/code choices are model-agent decisions. - Evidence: launchscientist.py, README.md, aiscientist/performexperiments.py. - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material first-party S2 coordination path is established. - Disturbance / variety regulated: multiple ideas may execute in parallel on different GPUs, but the workers are independent attempts; no concrete cross-S1 conflict/oscillation and attenuation relation is evidenced. - Decisive decision or feedback right: none established for S2. - Decision owner: none established for S2. - Supporting / enforcement mechanisms: multiprocessing queue, GPU assignment and independent per-idea workspaces. - Closure path: scheduling distributes independent jobs; it does not return a coordination decision to change behavior because of inter-S1 interference. - Why this is / is not agent-owned: resource scheduling is deterministic runtime support and parallelism alone is not S2. - Evidence: launchscientist.py. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no agent-owned whole-system current-control function is established. - Disturbance / variety regulated: failures/success at experiment/write-up/review stages change control flow, but stage ordering and stop/advance rules are fixed by the launcher. - Decisive decision or feedback right: no autonomous actor is shown holding a whole-run current view and discretionary authority over current shared resources, commitments, priorities or constraints. - Decision owner: none established for S3. - Supporting / enforcement mechanisms: launcher stage sequence, exceptions/return values, GPU/process setup, skip/improvement flags and fixed success gates. - Closure path: deterministic success/failure and CLI configuration drive stage transitions. - Why this is / is not agent-owned: local agents decide experiments/write-up content, while whole-run control remains scripted. - Evidence: launchscientist.py. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: independently challenge the produced research manuscript and, in the supported improvement mode, return findings into a separate corrective write-up path. - Disturbance / variety regulated: unsupported/unclear claims, presentation weaknesses, methodological weaknesses and other defects observable by a paper reviewer but not necessarily corrected during ordinary write-up. - Decisive decision or feedback right: produce a structured peer-review judgment/weakness set over the completed paper; those findings become explicit corrective input in improvement mode. - Decision owner: the first-party automated paper-review invocation, separate from the Aider writer/coder session being reviewed. - Supporting / enforcement mechanisms: PDF loading, review ensemble/reflections, persisted review.txt, performimprovement, PDF regeneration and second review. - Closure path: writer produces PDF -&gt; separate reviewer evaluates it -&gt; structured review/weaknesses -&gt; performimprovement(review, coder) returns findings to writer/coder -&gt; revised PDF -&gt; reviewer evaluates the revised artifact again. - Boundary reachability: --improvement is an explicit supported launcher mode using first-party review and improvement functions; it requires no external custom orchestration beyond normal model credentials. - Why this is / is not agent-owned: the reviewer owns the semantic challenge judgment; the launcher only transfers review findings and enforces the second pass. - Claim being audited: that the research manuscript adequately presents/supports the generated scientific work at peer-review quality. - Ordinary reporting path: experiment notes/results -&gt; manuscript generation by the coding/writing agent. - Complementary access path: a separate review invocation reads the rendered paper and evaluates it with a review-specific prompt/ensemble rather than reusing the writer conversation. - Independence boundary: writer/coder and reviewer are separate model interactions/roles; review is generated after the artifact is materialized. - Who acts on findings: the Aider writer/coder through performimprovement, followed by manuscript regeneration. - Evidence: launchscientist.py, aiscientist/performreview.py. - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S4 / adaptation: - State: A - Function: generate prospective research options, interrogate external literature for novelty and return novel ideas into current experimentation. - Disturbance / variety regulated: existing prior work may make a candidate idea non-novel; alternative ideas differ in feasibility/interestingness and should change the next experiment attempted. - Decisive decision or feedback right: propose/refine research ideas and, during novelty checking, choose literature queries and decide whether each idea is novel enough to enter the experiment set. - Decision owner: first-party idea-generation/novelty-checking model agents. - Supporting / enforcement mechanisms: idea reflection archive, Semantic Scholar/OpenAlex search, structured idea JSON, novelty flag and launcher filtering to novelideas. - Closure path: template/task context -&gt; agent proposes/refines idea -&gt; external literature searches return evidence -&gt; novelty judgment marks idea -&gt; only novel ideas are dispatched into executable experiments. - Boundary reachability: idea generation and novelty checking are invoked by the standard launcher unless explicitly skipped; their JSON/novelty outputs directly gate experiment admission. - Why this is / is not agent-owned: search APIs provide external observations, but query selection, idea refinement and novelty judgment are model-agent decisions. - External distinction: retrieved titles/abstracts/metadata from Semantic Scholar or OpenAlex. - Future / prospective distinction: whether a proposed idea is sufficiently novel/feasible/interesting to justify a future experiment. - Adaptation option generated: structured experiment idea with title, experiment outline and quality ratings. - Path back into current capability / S3: launcher filters ideas to novelideas and runs each accepted idea through doidea experiment/write-up execution. - Evidence: aiscientist/generateideas.py, launchscientist.py. - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no first-party identity/ultimate-policy closure is established. - Disturbance / variety regulated: experiment templates, prompt/task descriptions, model/engine flags and safety/container advice constrain operation, but no identity-level issue is routed to an ultimate authority. - Decisive decision or feedback right: none established for S5. - Decision owner: none established for S5. - Supporting / enforcement mechanisms: template prompt.json, CLI options, maintained template structure and static safety guidance. - Closure path: configuration/prompt/template policy directly constrains work; no identity/ultimate-policy decision loop is evidenced. - Why this is / is not agent-owned: research agents can select ideas/experiments but do not own authority to redefine the system&#39;s organizational identity or ultimate policy. - Evidence: README.md, launchscientist.py. - Basis: structural -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/c9da28372ac35ff5d8bc9a74679a6987a5d451df/assessments/ai-scientist.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit c9da28372ac35ff5d8bc9a74679a6987a5d451df\">c9da283 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-09-26T23:48:55+03:00\"><th scope=\"row\"><a href=\"https://github.com/nsidn98/LLaMAR\" target=\"_blank\" rel=\"noopener\">LLaMAR</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-26\">2026-09-26</time></td><td class=\"review-ref\"><a href=\"https://github.com/nsidn98/LLaMAR/tree/d2b74cac79a0f070d87a150712f8e2ae174920be\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision d2b74cac79a0f070d87a150712f8e2ae174920be\">d2b74ca &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: execute the embodied work required to complete the shared task through robot-specific actions in the environment. - Disturbance / variety regulated: partial observations, object locations/states, navigation/manipulation requirements, action failures and changing environment state during a long-horizon episode. - Decisive decision or feedback right: choose each robot&#39;s next substantive environment action from the current observations/state and interpret returned success/failure when selecting what happens next. - Decision owner: the first-party model-driven LLaMAR action/controller path over the embodied robot streams. - Supporting / enforcement mechanisms: AI2-THOR/SAR environment adapters, feasible-action mapping, per-agent observations/states/action histories, task/subtask state and deterministic execution plumbing. - Closure path: team task/current plan -&gt; model selects an action for each robot -&gt; environment executes each embodied action -&gt; per-agent observation/state/success/failure returns -&gt; later model call selects changed robot actions -&gt; episode progresses. - Boundary reachability: AI2Thor/baselines/llamar/llamar.py and SAR/baselines/llamar.py are shipped runnable first-party episode entrypoints and directly execute the credited action/environment feedback loop. - Why this is / is not agent-owned: simulator code transports actions and state, while the substantive next-action choices are model-generated from the live episode context. - Evidence: AI2Thor/baselines/llamar/llamar.py; AI2Thor/baselines/llamar/llamarutilsmultiagent.py; AI2Thor/envnew.py; SAR/baselines/llamar.py. - Basis: explicit + structural. - Confidence: high. - Caveats: next-action authority is centralized in the model call rather than separately modelled inside each physical robot, but the operational behavior is still first-party agent-owned at the assessed team boundary.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: - State: A - Function: attenuate concrete interference among simultaneously operating embodied robots sharing the same physical workspace. - Disturbance / variety regulated: robots blocking/bumping one another, congestion around shared objects/receptacles, one robot&#39;s manipulation/navigation preventing another robot from completing its assigned action, and unnecessary simultaneous movement into the same constrained area. - Decisive decision or feedback right: choose joint next-step actions such as waiting, moving aside, closing an obstruction or delaying one robot so another robot can proceed without cross-agent interference. - Decision owner: the first-party model-driven joint action/controller path using whole-team state and failure context. - Supporting / enforcement mechanisms: shared observations/state, previous action/failure fields, combined task/memory state, explicit anti-blocking prompt constraints and per-robot joint action output. - Closure path: multiple robot operations interact in one room -&gt; execution exposes cross-agent blocking/failure -&gt; the next model call reasons about the interference -&gt; assigns compensating actions across the involved robots -&gt; later robot behavior changes and the blocked operation can proceed. - Boundary reachability: the standard LLaMAR actor prompt is called on every episode step from the runnable baseline and directly receives/returns the team state and per-agent joint actions used by env.step(). - Why this is / is not agent-owned: the anti-interference choice is contextual model reasoning over current cross-agent state; deterministic code only executes the selected joint actions. - Evidence: AI2Thor/baselines/llamar/llamarutilsmultiagent.py; AI2Thor/baselines/llamar/llamar.py; AI2Thor/envnew.py. - Basis: explicit + structural. - Confidence: high. - Caveats: generic task allocation is not the basis for S2; the positive state rests on the separately evidenced physical interference problem and feedback relation. - Distinct S1 units: the concurrently acting embodied robot streams (Alice, Bob and additional configured robots), each with its own observation/state/action/success history and physical action effect. - Inter-S1 disturbance: one robot can physically block/bump another or occupy/open an object/path such that another robot&#39;s navigation/manipulation fails or must wait. - Attenuating coordination relation: the joint controller sees all robots&#39; state/history and is explicitly instructed to avoid blocking/bumping; failure reasoning can prescribe wait/move-aside/clear-path behavior across the involved robots. - Feedback into subsequent S1 behaviour: the model&#39;s coordinated per-robot action dictionary is passed through actionchecker and then to env.step(), changing the next embodied action of each robot. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the decisive witness is regulation of a concrete interaction disturbance among simultaneous embodied operations, not the existence of multiple robots, shared memory or a task decomposition graph.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A - Function: maintain the whole team&#39;s current task commitments and intervene in the active multi-robot plan as completion/failure/environment information changes. - Disturbance / variety regulated: changing team progress, completed versus still-open commitments, newly observed environment information and failures requiring the active plan or current robot allocation/actions to change. - Decisive decision or feedback right: decide the current shared open-subtask plan for the team and, through the whole-team action/controller stage, determine which operational action each robot should take now under that plan. - Decision owner: the first-party model-driven planner and whole-team action/controller path. - Whole-system current view: the planner receives the task, current observation from every configured robot, and the shared open/completed subtask state after each verifier step; the action/controller additionally receives every robot&#39;s state, previous action/failure, shared subtasks and combined memory. - Current-control decision scope: preserve or revise the team&#39;s active unfinished commitments and assign the next concrete actions/subtasks across the current robot population, including interventions after failures and current spatial conflicts. - Supporting / enforcement mechanisms: shared open/completed-subtask state, verifier updates, whole-team observation aggregation, combined memory, planner prompt, action/controller prompt and repeated plan-update loop. - Closure path: robot operations execute -&gt; team observations/actions and completion state update -&gt; verifier updates completed commitments -&gt; planner forms a revised whole-team open plan -&gt; action/controller maps that current plan/state to robot-specific next actions -&gt; changed operations execute and report back. - Boundary reachability: the planner/action stages are invoked in every standard runnable LLaMAR episode; no external orchestrator is required to form the whole-team view or return interventions into robot operation. - Why this is / is not agent-owned: the semantic choice of the current plan and per-robot intervention is model-driven; deterministic code stores plan/completion state and transports decisions into the environment. - Evidence: AI2Thor/baselines/llamar/llamar.py; AI2Thor/baselines/llamar/llamarutilsmultiagent.py; AI2Thor/envnew.py; SAR/baselines/llamar.py. - Basis: explicit + structural. - Confidence: high. - Caveats: S3 credit is not based on the component name Planner; it rests on the whole-team current view plus returned decisions changing the active shared commitments and robot actions.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: the verifier provides in-band completion reporting, but no materially independent complementary-audit function is established. - Disturbance / variety regulated: incorrect assumptions about whether a subtask has completed can be corrected before replanning, but the checked claim remains part of the ordinary task-progress loop. - Decisive decision or feedback right: no independent auditor with a distinct authority/evidence channel is established; the verifier prompt only classifies completed subtasks for the same episode. - Decision owner: none established for qualifying S3; the verifier uses the ordinary model service/configuration and shared episode evidence. - Supporting / enforcement mechanisms: verifier-specific prompt, all robot observations/states/previous actions, shared open/completed subtasks and combined memory. - Closure path: robot actions execute -&gt; ordinary episode observations feed verifier -&gt; completed-subtask list feeds planner -&gt; current plan changes; this is ordinary progress reporting/monitoring without an evidenced independent audit boundary. - Why this is / is not agent-owned: a semantic verifier exists, but verifier naming and a separate prompt-stage do not establish complementary independence. - Evidence: AI2Thor/baselines/llamar/llamar.py; AI2Thor/baselines/llamar/llamarutilsmultiagent.py; AI2Thor/envnew.py. - Basis: explicit + structural negative search. - Confidence: high. - Caveats: the verifier does influence subsequent planning; the missing requirement is organizational/complementary independence, not lack of feedback.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no material first-party prospective capability-adaptation loop is established beyond current-episode planning/replanning. - Disturbance / variety regulated: LLaMAR adapts its current task plan to new observations and failures, but does not evidence an actor that senses an external future environment, generates capability-change options and installs a change for later operational capability. - Decisive decision or feedback right: none established for prospective adaptation of the installed harness/robot organization across episodes. - Decision owner: none established for S4. - Supporting / enforcement mechanisms: current observation updates, planner replanning, memory and failure reasoning. - Closure path: environment change/failure -&gt; current episode replanning -&gt; changed immediate robot actions; no future-oriented capability option is implemented into later installed capability. - Why this is / is not agent-owned: current replanning is S1/S3 regulation, not evidence of S4 merely because the plan changes. - Evidence: AI2Thor/baselines/llamar/llamar.py; AI2Thor/baselines/llamar/llamarutilsmultiagent.py; README.md. - Basis: structural negative search. - Confidence: high. - Caveats: long-horizon planning and replanning are substantial capabilities but remain inside the present episode boundary.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no first-party runtime identity or ultimate-policy authority is established at the multi-robot episode boundary. - Disturbance / variety regulated: task text, model/configuration parameters, prompt rules and simulator limits constrain behavior but do not constitute identity-level adjudication. - Decisive decision or feedback right: none established for defining or reconciling the team&#39;s ultimate identity/purpose/policy under competing S3/S4 demands. - Decision owner: none established for S5. - Supporting / enforcement mechanisms: user-selected task/scene/configuration, static prompts and runtime constraints. - Closure path: external task/configuration enters directly as operating constraints; no identity-level issue -&gt; legitimate ultimate authority -&gt; policy decision -&gt; returned governance loop is evidenced. - Why this is / is not agent-owned: the models control current operational/coordination/management choices but do not choose the organization&#39;s ultimate identity or policy. - Evidence: README.md; AI2Thor/baselines/llamar/llamar.py; AI2Thor/baselines/llamar/llamarutilsmultiagent.py. - Basis: structural negative search. - Confidence: high. - Caveats: static system prompts describing robot roles/constraints are not S5 by themselves.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/a6735e44e0989bceeb433c4133d76671108cc563/assessments/llamar.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit a6735e44e0989bceeb433c4133d76671108cc563\">a6735e4 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-10-27T16:28:42+03:00\"><th scope=\"row\"><a href=\"https://github.com/DemonDamon/AgenticX\" target=\"_blank\" rel=\"noopener\">AgenticX</a><small>2024</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-10-27\">2026-10-27</time></td><td class=\"review-ref\"><a href=\"https://github.com/DemonDamon/AgenticX/tree/582c9d00bfb23efe6f7e588c3a5edfce570729bf\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 582c9d00bfb23efe6f7e588c3a5edfce570729bf\">582c9d0 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: perform open-ended user tasks by choosing tools, using execution results, and modifying task artifacts through root/child provider-backed agent sessions. - Disturbance / variety regulated: new task details, tool errors, repository content, provider responses and subtask outcomes. - Decisive decision or feedback right: choose next model tool call, interpret feedback and continue/revise an execution plan. - Decision owner: configured model-backed AgentRuntime/ReAct root and spawned agents; neither the SDK Agent data model nor the event queue owns model reasoning. - Supporting / enforcement mechanisms: provider resolver, agent/tool loop, Studio session persistence, subagent context/tool permissions and callbacks. - Closure path: model chooses a tool, runtime executes it, the result enters the same agent&#39;s context, and later decisions change task output. - Boundary reachability: this path is shipped both through the agx/Studio local backend and embedded SDK; Near&#39;s default app starts this local runtime. - Why this is / is not agent-owned: the agent model makes contextual tool/continuation decisions; host code supplies guardrails and transport. - Evidence: AgentRuntime, ReActAgent, Studio server Meta-Agent setup. - Basis: explicit and structural. - Confidence: high. - Caveats: successful live provider/model execution and claimed production quality were not measured.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no evidence-backed distinct relation that autonomously attenuates an identified interference among simultaneously acting S1 units, beyond task partition and bounded queueing. - Disturbance / variety regulated: potential overlap of parallel workers, resource contention and conflicting changes would require interference-specific handling. - Decisive decision or feedback right: no first-party agent-owned cross-worker conflict detection, reconciliation or isolation decision shown as an operationally closed coordination loop for the declared Studio team. - Decision owner: none established at S2; the model planner assigns tasks and host TaskLock transports actions. - Supporting / enforcement mechanisms: Team task decomposition, worker assignments/dependencies, TaskLock action queue, group routing and shared context. - Closure path: delegations can complete and summaries return, but that is ordinary task routing; no distinct detected inter-S1 collision and corrective relation is evidenced. - Why this is / is not agent-owned: naming a CoordinatorAgent or serializing actions does not establish function-specific S2 conflict attenuation. - Distinct S1 units: concurrent model-backed child agents. - Inter-S1 disturbance: same-file edits or contested resources are plausible, but the inspected supported team path does not independently establish a response to an observed conflict. - Attenuating coordination relation: no qualifying inter-S1 relation established; task lists and a queue prevent generic scheduling races, not semantically competing work ownership. - Feedback into subsequent S1 behaviour: worker results and messages return to the manager/leader, but without a verified conflict-specific control decision. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: S2-specific ownership is not credited for generic dispatch or action queue operations. - Evidence: Team mode wiring and TaskLock, TaskLock, WorkforcePattern. - Basis: structural. - Confidence: medium. - Caveats: developers may compose custom S2 adapters with the SDK; that is not automatically the shipped Studio default.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A - Function: supervise the current root-session team by observing children and deciding when to spawn, communicate, retry or cancel during live task delivery. - Disturbance / variety regulated: active child runs may stall/fail, saturate concurrency or CPU/memory, need new work or require intervention to meet the immediate user task. - Decisive decision or feedback right: select and invoke status query, spawn/cancel/retry/message subagent tools in light of reported current child state and goals. - Decision owner: configured root model-backed Meta-Agent within the supported Studio session, not the AgentTeamManager or the deterministic ResourceMonitor. - Supporting / enforcement mechanisms: AgentTeamManager actual live status registry, timeouts, caps and resource admission checks; root Meta-Agent tool dispatcher; Studio event stream. - Closure path: root sees team status/tool results, chooses a current-team intervention, AgentTeamManager changes a child run/permission to launch, and updated state returns to the root&#39;s next model turn. - Boundary reachability: Studio builds the root Meta-Agent with visible team-management tools, and the attached AgentTeamManager executes them on real session children in the shipped local backend. - Why this is / is not agent-owned: current worker-team decisions are controlled by the root model, while deterministic caps merely reject inadmissible actions. - Whole-system current view: querysubagentstatus and team status provide running/completed/failed child state and resource-monitor context for the session team. - Current-control decision scope: the current portfolio of active/retryable child agents in one root session, including admission and cessation; not Enterprise gateway quotas or an unrelated Studio user. - Evidence: team lifecycle/status/cancel, meta tool handler, resource monitor. - Basis: explicit and structural. - Confidence: medium-high. - Caveats: the model might choose not to use these tools; the claim is an available integrated operational loop, not a guaranteed policy of continuous proactive optimization.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no independently controlled complementary reality-audit path with corrective control established for the current Studio session team. - Disturbance / variety regulated: an executor can mistakenly report complete work while the real environment differs. - Decisive decision or feedback right: no independent auditor&#39;s direct-evidence veto/intervention against the team report established in the selected operating mode. - Decision owner: none established; SDK evaluation/LLM judge and Enterprise audit logging are separate or routine surfaces. - Supporting / enforcement mechanisms: traces, tool results, observability and optional evaluation framework. - Closure path: tests/evaluations can be explicitly launched, but a first-party independently owned standing complementary team audit with returned corrective control is not demonstrated. - Why this is / is not agent-owned: evaluation APIs, group worker results and log chains cannot substitute for a separate auditor owner. - Evidence: evaluation/observability overview, team results, Enterprise gateway separation. - Basis: structural. - Confidence: medium. - Caveats: externally composed independent reviewers are possible through the SDK, but their independence cannot be credited to the shipped session team.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S4 / adaptation: - State: A(P) - Function: convert observations of changing external tool/provider/task conditions and user corrections into future reusable skill capability for subsequent sessions. - Disturbance / variety regulated: repeated external tool failures, newly learned environment conventions and multi-step strategies that existing installed skills do not yet encode. - Decisive decision or feedback right: the background model-backed review agent decides whether and how to create/patch a reusable skill; under the normal supervised mode the Desktop operator separately decides whether to approve the proposed future capability. - Decision owner: opt-in skill-review agent in the direct-authorized mode (A), and legitimate Desktop-user approver for a separately supported queued-proposal mode (P). These modes are not simultaneous autonomous governance. - Supporting / enforcement mechanisms: registered SessionReviewHook, actual tool observation records, signal/complexity gate, configured review model, skillmanage, skill policy scan, pending proposals and desktop approval endpoint. - Closure path: a completed tool-using session triggers a review of observed attempts/errors/user corrections; the model proposes a skill; in explicitly authorized direct mode it writes the skill for later sessions, while in default queue mode the Desktop user approves the same proposed document and installs it. Later model runs can discover/use the changed skill collection. - External distinction: observations concern user corrections and tool/provider outcomes from the task environment, not just the host runtime&#39;s own counters; the model interprets their reusable implications. - Future / prospective distinction: a post-session reviewer encodes a method for later task contexts rather than repairing only the completed current task, and the installed skill survives that session boundary. - Adaptation option generated: choose a new action-oriented skill or a patch to an existing skill, including the specific steps and guardrails for future comparable disturbances. - Path back into current capability / S3: after authorized direct installation or Desktop-user approval, the skill is added to the local installed registry so a later Meta-Agent/runtime session can discover and use the revised capability under its current task controls. - Boundary reachability: AgentRuntime registers SessionReviewHook; learning.reviewenabled is an active shipped configuration option, agentwritesrequireapproval distinguishes queue versus direct install, and Studio/Near expose proposal inspection/approve/reject routes. Both paths require configured model/provider access; neither is default-on just because observation is enabled. - Why this is / is not agent-owned: the reviewer model selects substantive future reusable methods, not just a deterministic score; the operator retains the separate approval right in the supervised mode.\">A(P)</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no closed ultimate-purpose or identity-policy governance path for the local Studio agent-team recursion. - Disturbance / variety regulated: conflicts about the team&#39;s permanent charter, legitimacy or non-negotiable identity beyond ordinary tasks/permissions. - Decisive decision or feedback right: no runtime identity-level final authority and returned policy choice established in the selected local session hierarchy. - Decision owner: none established for this function; product maintainers, Enterprise administrators and local user are adjacent authorities for different matters. - Supporting / enforcement mechanisms: operator permissions, skill-approval gate, safety policies, user prompts, Enterprise Gateway policies and contributor governance. - Closure path: users permit/deny operations, administrators configure Gateway routing, and skill approvals modify future capabilities; these are operational/safety/adaptation choices rather than a reconstructed identity-level decision loop in local Studio. - Why this is / is not agent-owned: a Meta-Agent CEO label does not create sovereign identity control, and separate enterprise governance does not transfer to deployed Studio S5. - Evidence: runtime/Enterprise boundaries, Studio tool gates, Meta-Agent identity prompt. - Basis: structural. - Confidence: medium. - Caveats: no finding about how the open-source project or enterprise tenants should normatively govern themselves is made.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/d83ab15f2643bc53884a269c9555beaea45091fb/assessments/ag/agenticx.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit d83ab15f2643bc53884a269c9555beaea45091fb\">d83ab15 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-09-29T17:45:27Z\"><th scope=\"row\"><a href=\"https://github.com/pipecat-ai/pipecat\" target=\"_blank\" rel=\"noopener\">Pipecat</a><small>2023</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-29\">2026-09-29</time></td><td class=\"review-ref\"><a href=\"https://github.com/pipecat-ai/pipecat/tree/dbdf21a017f86624fb7768e35730417169524e0d\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision dbdf21a017f86624fb7768e35730417169524e0d\">dbdf21a &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: perform an environment-facing conversational/agent task by selecting model responses and model-callable tools from live input/context and incorporating tool/service outcomes into subsequent operation. - Disturbance / variety regulated: user utterances, conversation state, tool needs/results, external-service responses, media events and task-specific runtime outcomes. - Decisive decision or feedback right: choose the substantive next response/tool action in the shipped model/tool loop. - Decision owner: the configured LLM actor invoked through Pipecat&#39;s first-party LLM service/pipeline surfaces. - Supporting / enforcement mechanisms: context aggregators; tool schemas/callbacks; transports; pipeline frames; jobs; timeouts; service adapters; tracing/metrics. - Closure path: user/environment input enters pipeline → Pipecat constructs model context/tools → model chooses response/tool action → runtime executes/delivers it → observations/results are returned into later context and operation. - Boundary reachability: this is Pipecat&#39;s ordinary supported runtime, not a repository-development-only example. - Why this is / is not agent-owned: removing the model decision actor leaves transport/execution machinery but removes the open-ended choice of conversational/task action. - Evidence: README.md; llmworker.py; openclaw-agent.py. - Basis: explicit + structural. - Confidence: high. - Caveats: provider implementation is external, but Pipecat deliberately places the model actor inside its supported operational feedback loop.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: - State: A - Function: attenuate concurrent/interleaved output interference between distinct autonomous LLM workers during a live handoff and ensure that only the selected worker owns the next conversational operation. - Disturbance / variety regulated: the target worker can begin producing while the source worker still has output in flight, causing both workers&#39; outputs to arrive interleaved; overlapping activation would make ownership of the user-facing turn ambiguous. - Decisive decision or feedback right: decide when to transfer conversational ownership from the current autonomous worker to another worker in response to the live conversation. - Decision owner: the currently active LLM worker in the first-party local-handoff mode, through the model-callable transfertoagent tool. - Supporting / enforcement mechanisms: activateworker; source-pipeline drain; mutually exclusive activation/deactivation; shared worker registry/bus; tool result that suppresses another current LLM run during transfer. - Closure path: current LLM observes conversation → model selects transfertoagent → source worker drains outstanding output → runtime deactivates source and activates target without overlap → subsequent user-facing operation is produced by the selected target worker. - Boundary reachability: the behavior is implemented by first-party worker APIs and exercised by a runnable first-party multi-worker example whose documentation explicitly states that the LLM decides when to transfer. - Distinct S1 units: the active greeter/customer-service LLMWorker and the target support LLMWorker are separate model-driven operational workers sharing the conversation transport through the worker runtime. - Inter-S1 disturbance: without handoff drainage/exclusivity, the target worker can begin producing while the source worker still has output in flight, and both outputs can arrive interleaved. - Attenuating coordination relation: activateworker drains the source pipeline, deactivates it, then activates the selected target so the two workers do not simultaneously own user-facing output. - Feedback into subsequent S1 behaviour: after the model-selected handoff, the target worker becomes active and receives/acts on subsequent conversation turns while the source is inactive. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the mechanism exists to attenuate a documented interference between two autonomous operational workers, and its result changes their subsequent operational participation; credit does not rely on WorkerBus messaging or delegation alone. - Why this is / is not agent-owned: the runtime enforces safe switching, but the semantic choice of when/where to transfer is made by the active model from live conversational evidence. Removing that model decision leaves a callable handoff primitive, not the same coordination judgment. - Evidence: local-handoff-two-agents.py; worker.py; baseworker.py. - Basis: explicit + structural. - Confidence: high. - Caveats: generic WorkerBus messaging/job routing is not used as S2 evidence; credit depends on the concrete interleaving disturbance and the model-selected handoff closure.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A - Function: regulate the current subordinate agent commitment while preserving a responsive voice/conversation loop. - Disturbance / variety regulated: long-running delegated work can be idle, active, obsolete after a user correction, redirected, cancelled, failed or completed while the conversational front end continues receiving new input. - Decisive decision or feedback right: from live subordinate-job state, choose whether to dispatch/update work, inspect current status or preemptively stop the active subordinate commitment. - Decision owner: the voice LLM in the first-party OpenClaw-agent composition; its context exposes sendtoagent, stopagent and agentstatus as model-callable tools. - Supporting / enforcement mechanisms: ActiveJob; bus job requests/updates/responses; job-group cancellation; WorkerRunner; OpenClaw worker; developer messages that return job outcomes to the voice model. - Closure path: voice LLM receives current user input plus returned job state/outcome → model chooses direct response or a current-control tool → Pipecat dispatches/updates, reports or cancels the subordinate job → bus update/response changes ActiveJob and is returned to the voice loop → later current-control decisions use the changed state. - Boundary reachability: the complete path is a runnable first-party multi-worker example built on public first-party worker/job APIs. - Whole-system current view: at the selected voice-plus-agent recursion, the voice regulator tracks the only subordinate operational commitment (jobid, request, start time and later response/update state) while continuing its own user-facing work. - Current-control decision scope: it can create/change the live delegated commitment and preempt it; this is stronger than read-only status or runtime lifecycle cleanup. - Why this is / is not agent-owned: the LLM itself selects the exposed dispatch/status/stop tools from current conversational evidence. Runtime code transports/enforces those choices; it does not make an equivalent semantic judgment when the model is removed. - Evidence: openclaw-agent/README.md; openclaw-agent.py; runner.py. - Basis: explicit + structural. - Confidence: medium-high. - Caveats: the OpenClaw backend decides whether a forwarded update starts a new internal turn or steers an existing one. S3 credit is not assigned to that backend decision; it is assigned to Pipecat&#39;s model-facing authority to observe, issue/update and cancel the current subordinate commitment at this recursion. Generic WorkerRunner end/cancel behavior alone would be constructor lifecycle support, not agent-owned S3.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no material first-party complementary audit loop was established that independently inspects current operational claims and returns findings into the live operation/current-control loop for corrective work. - Disturbance / variety regulated: Pipecat can evaluate bot conversations and report assertion/judge failures, but those evaluation outcomes are separate test/eval results rather than a shipped production correction loop. - Decisive decision or feedback right: not established for S3 at the assessed runtime boundary. - Decision owner: not applicable. - Supporting / enforcement mechanisms: scripted and simulated eval drivers; optional EvalJudge; expectation matching; pass/fail result objects; traces; ordinary worker job responses/errors. - Closure path: no S3-specific corrective closure established. Eval failures can stop or continue an evaluation scenario and are reported to the evaluator/caller, but the reviewed runtime does not feed a distinct auditor finding back into the audited bot&#39;s current work to require revision/retry. - Why this is / is not agent-owned: a separate judge exists, but independence alone is insufficient; the missing production feedback closure prevents classification as A or C S3. - Evidence: scriptdriver.py; simulation.py; openclaw-agent.py. - Basis: explicit + structural negative finding. - Confidence: high. - Caveats: downstream applications can consume eval failures and implement corrective loops; caller composition is not credited as first-party Pipecat closure without shipped wiring.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no material first-party external-and-prospective adaptation loop was established that converts environmental distinctions into persistent changes of Pipecat operating capability/policy used by later work. - Disturbance / variety regulated: persistent conversation memory and dynamic current-session flow/context exist, but no reviewed mechanism closes prospective capability adaptation. - Decisive decision or feedback right: not established for S4. - Decision owner: not applicable. - Supporting / enforcement mechanisms: Mem0 message storage/search; LLM conversation context; flow transitions and role messages; runtime LLM settings updates; session continuation. - Closure path: no S4-specific closure established. Mem0 stores user/assistant messages and retrieves relevant memories into later context; it does not itself decide or persist a changed skill/tool/policy/capability in response to external/future distinctions. - Why this is / is not agent-owned: memory continuity and current-flow reconfiguration can affect future responses, but the reviewed first-party code does not contain the required sensing → prospective adaptation judgment → persistent capability change → reuse loop. - Evidence: memory.py; flows/manager.py; llmcontext.py. - Basis: explicit + structural negative finding. - Confidence: high. - Caveats: a downstream agent can use Pipecat tools to build its own learning/adaptation system; that is outside this standalone runtime assessment.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no runtime identity/ultimate-policy loop with legitimate ultimate authority and returned closure was established at the assessed recursion. - Disturbance / variety regulated: bots can have durable system instructions, role messages and application-authored rules, but these are configured operating instructions rather than an S5 adjudication loop. - Decisive decision or feedback right: an S5 witness would require an unresolved identity/ultimate-policy issue to reach a legitimate parent/ultimate authority and the resulting policy decision to return into later operation; no such first-party path was established. - Decision owner: not established for S5. - Supporting / enforcement mechanisms: configured systeminstruction; Flow rolemessage; tool schemas; application code; provider/session settings. - Closure path: no S5-specific escalation-and-return path established. Pipecat can apply or update instructions supplied by the application, but that is instruction transport/current configuration rather than ownership of identity or ultimate policy. - Why this is / is not agent-owned: neither static developer-authored identity nor runtime system-instruction mutation by framework/application code establishes a legitimate ultimate-policy decision loop under Profile 0.2.4. - Evidence: flows/manager.py; llmservice.py; uiworker.py. - Basis: explicit + structural negative finding. - Confidence: high. - Caveats: downstream product owners may govern bot identity out of band; this assessment does not convert arbitrary application configuration into Pipecat S5 ownership.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/2f9af52d3fefcbb27eb35f8f736f06a8ef93e432/assessments/pipecat.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 2f9af52d3fefcbb27eb35f8f736f06a8ef93e432\">2f9af52 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-09-16T23:24:44+03:00\"><th scope=\"row\"><a href=\"https://github.com/microsoft/autogen\" target=\"_blank\" rel=\"noopener\">Microsoft AutoGen AgentChat</a><small>2023</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/microsoft/autogen/tree/027ecf0a379bcc1d09956d46d12d44a3ad9cee14\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 027ecf0a379bcc1d09956d46d12d44a3ad9cee14\">027ecf0 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: stateful agents choose tools/actions and incorporate returned results.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: team selection plus Magentic-One&#39;s explicit loop/stall detection and controlled transfer of the next action right suppress uncontrolled repetition/interference among multiple S1 participants. This is more than mere delegation.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: MagenticOneOrchestrator owns a whole-team current facts/plan/progress ledger and has authority to assess progress, choose commitments, reset participants and regenerate the plan when the team stalls. Code-execution approval constrains an operational executor action rather than independently owning this whole-team current-control loop, so no separate (P) mode is published.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: the progress ledger is part of the same operational S3 regulator that directs the team. It is not a distinct complementary audit channel with separate reviewing independence.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: replanning after current-task stalls is inside-now adaptation. No distinct external/prospective intelligence function shaping future organizational posture is established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: participant set, instructions, termination rules and ultimate authority remain application/parent-owned.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/9ee1ea7472777767928c8b2ab035e0948a0467e9/assessments/autogen-agentchat.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 9ee1ea7472777767928c8b2ab035e0948a0467e9\">9ee1ea7 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-09-20T21:45:19+03:00\"><th scope=\"row\"><a href=\"https://github.com/Technion-Kishony-lab/data-to-paper\" target=\"_blank\" rel=\"noopener\">data-to-paper</a><small>2023</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-20\">2026-09-20</time></td><td class=\"review-ref\"><a href=\"https://github.com/Technion-Kishony-lab/data-to-paper/tree/81df14c4b9600466e645c3b2b336cc54daa3df3a\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 81df14c4b9600466e645c3b2b336cc54daa3df3a\">81df14c &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: autonomously perform the environment-facing scientific work needed to transform project data and research state into executable analyses and research artifacts. - Disturbance / variety regulated: heterogeneous datasets, generated-code errors, unexpected outputs/files, statistical-analysis requirements, intermediate product state and manuscript construction requirements. - Decisive decision or feedback right: choose and revise analysis/code/content actions in response to current project products, execution results and validation/reviewer feedback. - Decision owner: the active first-party performer/code-writing agents in the hypothesis-testing workflow. - Supporting / enforcement mechanisms: stage runner, CodeRunner, debugger conversers, code extract/check logic, output requirements, product store, data chaining and configured iteration bounds. - Closure path: current scientific products/data -&gt; agent proposes code/content action -&gt; first-party runner executes/materializes it -&gt; output/error/product state returns -&gt; agent revises or advances. - Boundary reachability: these paths are the shipped hypothesis-testing research workflow invoked by the installable application/CLI, not benchmark-only examples. - Why this is / is not agent-owned: runtime and guardrails execute/check code, but the context-sensitive analysis/content choice and revision remain model-agent decisions. - Evidence: README.md, stepsrunner.py, requestcode.py. - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material first-party S2 coordination path is established at the reviewed recursion. - Disturbance / variety regulated: the workflow contains multiple performer/reviewer roles and research stages, but no concrete interference, conflict or oscillation among distinct S1 units is identified and attenuated by a dedicated coordination relation. - Decisive decision or feedback right: none established for S2. - Decision owner: none established for S2. - Supporting / enforcement mechanisms: typed stage transitions, product passing, paired conversations, deterministic sequencing and rewind/retry utilities. - Closure path: these mechanisms sequence work and transmit review feedback; they do not close a cross-S1 interference-regulation loop. - Why this is / is not agent-owned: interacting agents and state transfer are real, but the reviewed paths are production/review dependencies rather than S2-specific conflict attenuation. - Evidence: stepsrunner.py, dualconverser.py. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no autonomous whole-system inside-and-now control function is established at the reviewed recursion. - Disturbance / variety regulated: stage completion, retries, rewinds, project parameters and review rounds constrain current work, but no first-party autonomous actor is shown holding a whole-project current view plus broad authority over shared resources/commitments/priorities. - Decisive decision or feedback right: stage flow and retry bounds are primarily encoded in deterministic runner logic and project parameters; local reviewers control product acceptance rather than organization-wide current control. - Decision owner: none established for S3. - Supporting / enforcement mechanisms: DataStepRunner/HypothesisTestingStepsRunner, stage enums, product readiness, retry/rewind helpers, project parameters and UI actions. - Closure path: configured stage/retry conditions alter control flow mechanically; no discretionary whole-system S3 owner is evidenced. - Why this is / is not agent-owned: model agents make local scientific/product decisions, while the broader workflow sequence is framework-defined. - Evidence: stepsrunner.py, README.md. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: provide a separate challenge channel that reviews scientific/code/writing products and returns concrete corrective feedback before those products are accepted. - Disturbance / variety regulated: plausible-but-wrong analysis outputs, code/result problems, weak hypotheses/plans, writing defects and other product claims that ordinary performer generation may miss. - Decisive decision or feedback right: independently approve a product or issue constructive concerns that force another performer revision cycle. - Decision owner: the separate reviewer LLM conversation in ReviewDialogDualConverserGPT and review-specific subclasses; in code paths, review agents inspect executed outputs/code products separately from the generating/debugging conversation. - Supporting / enforcement mechanisms: separate ConversationManager, review termination phrase, max review rounds, product extraction/checks, code-review prompts and rewind utilities. - Closure path: performer produces valid candidate -&gt; reviewer receives the candidate/background -&gt; reviewer approves or supplies concerns -&gt; concerns are appended to the performer conversation with explicit correction request -&gt; performer rewrites/revises -&gt; review repeats. - Boundary reachability: the review dialog base class is reused by goal, planning and manuscript-writing review steps in the shipped hypothesis-testing workflow; code review is also embedded in the standard code-product path. - Why this is / is not agent-owned: the reviewer is a separate agent conversation and owns the semantic approve/challenge judgment; deterministic loop code only routes/enforces that judgment. - Claim being audited: that a current scientific product/code result is adequate/correct enough to become accepted workflow state. - Ordinary reporting path: performer response plus normal generated/executed product state. - Complementary access path: separate reviewer conversation receives the product and relevant background/output context; code review can inspect created output contents. - Independence boundary: reviewer has its own conversation manager/role and does not share the performer&#39;s assistant role; review feedback is generated independently and then returned. - Who acts on findings: the original performer/code-writing agent revises the product in the next cycle. - Evidence: dualconverser.py, requestcode.py, stepsrunner.py. - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S4 / adaptation: - State: A(P) - Function: use external literature/novelty evidence to develop or revise future research direction and return the selected direction into the current experimental plan, with both autonomous and Copilot parent-governed modes. - Disturbance / variety regulated: existing literature may make a candidate goal non-novel, external findings may change relevant hypotheses, and a human scientist may judge the proposed future direction inadequate. - Decisive decision or feedback right: in Autopilot, research/novelty agents judge literature-derived novelty and generate/refine the goal/hypothesis; in Copilot, human review can replace/supplement reviewer feedback and require revised research products. - Decision owner: autonomous research/reviewer agents in base mode; human scientist in the supported Copilot parent mode for the reviewed future-direction decision. - Supporting / enforcement mechanisms: literature-search agents, NoveltyAssessmentReview, ReGoalReviewGPT, stage return to GOAL, human-review application interactions, product storage and plan handoff. - Closure path: external literature -&gt; novelty/goal review -&gt; autonomous or parent judgment -&gt; if inadequate, workflow returns to goal generation/refinement -&gt; resulting goal/hypothesis/testing plan feeds data analysis and later research stages. - Boundary reachability: literature/novelty/goal refinement is part of the shipped hypothesis-testing runner, and README plus HumanReviewType/review interaction code expose Copilot human feedback through the same first-party workflow. - Why this is / is not agent-owned: the base mode closes without human direction through model-agent novelty/refinement decisions; the separately supported Copilot mode intentionally transfers the relevant review/judgment right to the human and returns that decision into workflow state. - External distinction: retrieved scientific literature and most-similar-paper evidence. - Future / prospective distinction: whether the current research goal/hypothesis is novel/appropriate enough to warrant future experimentation. - Adaptation option generated: revised research goal/hypothesis and downstream hypothesis-testing plan. - Path back into current capability / S3: failed novelty sets regoal and returns to ScientificStage.GOAL; accepted/revised goal then feeds planning, code analysis and manuscript stages. - Evidence: stepsrunner.py, dualconverser.py, README.md. - Basis: structural -\">A(P)</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no first-party identity/ultimate-policy closure is established. - Disturbance / variety regulated: project parameters, research goals, human feedback and methodological guardrails constrain work, but no identity-level dispute is routed to an ultimate authority and returned as governing organizational policy. - Decisive decision or feedback right: none established for S5. - Decision owner: none established for S5. - Supporting / enforcement mechanisms: startup/project parameters, user research goal, coding guardrails, reviewer prompts and human-review UI. - Closure path: these controls constrain local research behavior directly; no identity/ultimate-policy issue -&gt; authoritative decision -&gt; returned policy loop is evidenced. - Why this is / is not agent-owned: neither autonomous agents nor the Copilot human are shown resolving an identity-level policy issue at this recursion. - Evidence: README.md, stepsrunner.py. - Basis: structural -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/c9da28372ac35ff5d8bc9a74679a6987a5d451df/assessments/data-to-paper.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit c9da28372ac35ff5d8bc9a74679a6987a5d451df\">c9da283 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"1\" data-assessment-at=\"2026-09-21T19:11:00+03:00\"><th scope=\"row\"><a href=\"https://github.com/zhayujie/CowAgent\" target=\"_blank\" rel=\"noopener\">CowAgent</a><small>2022</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-20\">2026-09-20</time></td><td class=\"review-ref\"><a href=\"https://github.com/zhayujie/CowAgent/tree/7c55a61e1bccb82c99d97a4a436f598c079f7c9d\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 7c55a61e1bccb82c99d97a4a436f598c079f7c9d\">7c55a61 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: autonomously transform user/scheduled/delegated objectives into environment-facing tool/skill work and returned outcomes. - Disturbance / variety regulated: heterogeneous user objectives, model uncertainty, tool results/errors, files/shell/browser/service state, channel messages, and follow-up observations encountered during a trajectory. - Decisive decision or feedback right: choose the next reasoning/tool/skill action, incorporate returned observations, delegate bounded work when useful, or stop with a final response. - Decision owner: the running CowAgent Agent/model actor inside the first-party AgentStreamExecutor loop. - Supporting / enforcement mechanisms: ChatService, AgentBridge, provider adapters, prompt/workspace construction, tool registry, permissions, session persistence, scheduler integration and context controls. - Closure path: each tool result, delegated result or new model observation returns into the first-party executor context and can change the next autonomous action until completion. - Boundary reachability: the credited executor/bridge/tool path is the normal shipped Web/channel runtime and is instantiated directly by standard CowAgent operation at the pinned revision. - Why this is / is not agent-owned: deterministic code supplies transport, limits and execution, while the model actor owns the discretionary next-action choice on each loop iteration. - Evidence: pinned agent/chat/service.py and bridge/agentbridge.py; README.md corroborates the shipped planning/tool execution boundary. - Basis: structural and explicit. - Confidence: high. - Caveats: model/provider/tool availability, permissions and iteration limits constrain the Agent&#39;s operational discretion but do not replace its next-action judgment.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: attenuate a concrete interference between sibling operational Agents when concurrent delegations target the same persistent relay conversation. - Disturbance / variety regulated: concurrent handoffs to one source→target relay session would otherwise interleave turns in the target Agent&#39;s transcript and corrupt the shared conversational state used by later delegated work. - Decisive decision or feedback right: serialize admission to that target relay session so exactly one delegated turn occupies it at a time; timeout rather than permit an overlapping handoff when the lock cannot be acquired within policy. - Decision owner: constructor-owned at the assessed boundary. The first-party S2-specific serialization primitive is complete and operational, but the conflict policy itself is deterministic/developer-selected rather than autonomously chosen by an Agent. - Supporting / enforcement mechanisms: per-relay relaylock, stable relay-session derivation, delegation roster/ACL, depth/cycle checks, timeout and synchronous result return. - Closure path: a source Agent&#39;s delegation blocks on the relay lock; after the prior target turn finishes and releases the lock, the next delegated target run executes against a non-interleaved transcript and its result returns to the waiting source Agent, changing that source&#39;s subsequent S1 behavior. - Boundary reachability: agentdelegate is a shipped team tool attached to normal team turns through AgentBridge; no downstream coordinator or test-only actor is required for the serialization path. - Why this is / is not agent-owned: Agents autonomously decide to delegate and select the teammate/task, but once two handoffs conflict the coordination choice is a fixed first-party lock policy. CowAgent therefore exposes a real S2-specific construction path without an autonomous owner of the conflict-regulation decision. - Evidence: pinned agent/tools/agentdelegate/agentdelegate.py and team-session support in bridge/agentbridge.py. - Basis: structural. - Confidence: high. - Caveats: other team features such as speaker selection, shared transcripts and ordinary handoff are not separately credited as S2 merely because they connect Agents. - Distinct S1 units: independently configured live CowAgent Agents with separate profiles/workspaces and first-party execution loops participating in one team conversation. - Inter-S1 disturbance: overlapping delegated turns to the same target relay session can interleave in the target transcript. - Attenuating coordination relation: the first-party per-relay lock queues competing handoffs and allows only one target turn at a time. - Feedback into subsequent S1 behaviour: the coordinated target result is returned synchronously to the delegating source Agent&#39;s tool loop; timeout/failure likewise returns a result that changes the source Agent&#39;s next decision. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the lock exists specifically because concurrent sibling handoffs would interfere by interleaving one operational transcript, and it changes admission/timing to suppress that identified disturbance before results feed back to the source Agent.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S3 / regulation: - State: P - Function: regulate the currently configured CowAgent installation as a whole by changing which operational Agents are available, which models/capabilities they use, and which live channel instances/teams route work to them. - Disturbance / variety regulated: current mismatch between installed operational capacity and the operator&#39;s desired roster, agent availability, model/capability allocation, shared/own knowledge mode, default ownership and live channel/team bindings. - Decisive decision or feedback right: create/update/archive/delete an Agent, make an Agent default, enable/disable it, alter its model/skills/knowledge allocation, or rebind a running channel/team to a different Agent roster. - Decision owner: the authenticated self-hosted operator is the legitimate parent actor in this supported mode. - Supporting / enforcement mechanisms: AgentAdminService, roster revision checks, Web authentication, registry/router rebuilding, scheduler reconciliation, targeted live-runtime eviction and hot channel rebinding. - Closure path: the operator submits a first-party Web/API decision; CowAgent persists it, updates the live registry/router or channel binding, starts/stops the affected schedulers and evicts changed Agent instances so subsequent current work is executed under the returned control decision. - Boundary reachability: the authenticated Web console and its /api/agents administration paths are a standard shipped self-hosted operating surface documented as the unified configuration hub, not a development-only control plane. - Why this is / is not agent-owned: no standard first-party autonomous Agent is given installation-wide roster/model/capability/channel authority. The decisive current-control choice comes from the authenticated operator; runtime code only validates, persists and enforces it. - Evidence: pinned agent/admin.py, channel/web/api/agents.py, and bridge/agentbridge.py scheduler/runtime reconciliation. - Basis: explicit and structural. - Confidence: medium-high. - Caveats: this claim is limited to installation-level current capability/resource control. Per-task steering/cancel and permission enforcement alone would not establish S3, and the assessment does not treat every settings edit as an S3 decision. - Whole-system current view: AgentAdminService.snapshot() exposes the installation&#39;s full current Agent roster, default Agent and channel instances; the same authenticated surface operates over that roster rather than one worker-local state. - Current-control decision scope: availability of S1 units, current model/capability allocation, default Agent, channel/team routing and scheduler participation for the running installation.\">P</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no material first-party complementary and sufficiently independent audit function was established at the declared installation boundary. - Disturbance / variety regulated: none established as an S3 witness; ordinary tool feedback, run/event recording and Self-Evolution review do not provide a materially independent route to operational reality for checking production claims. - Decisive decision or feedback right: no S3-specific independent audit judgment/feedback right is supplied. - Decision owner: not established. - Supporting / enforcement mechanisms: execution/tool events, conversation/run persistence, evolution records/backups, logs and operator inspection surfaces. - Closure path: no independent audit finding→corrective-current-control loop was established; recorded events and evolution changes serve their primary execution/adaptation purposes. - Why this is / is not agent-owned: there is no qualifying audit function whose decisive judgment could be assigned to an autonomous Agent. - Evidence: pinned chat/executor event path, conversation storage, Web/admin surfaces, and agent/evolution/ review path. - Basis: structural. - Confidence: high. - Caveats: a downstream deployment could add an independent verifier or external monitor, but that composed system would be outside this frozen first-party boundary.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:4\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S4 / adaptation: - State: A - Function: convert externally observed conversation patterns and capability failures into prospective adaptations of reusable future capability. - Disturbance / variety regulated: changing user preferences and recurring work patterns, skill defects discovered in real use, reusable workflows not yet encoded as capabilities, and unfinished work whose recurrence or omission would reduce future fit. - Decisive decision or feedback right: after an idle conversation, decide autonomously whether there is a clear durable signal and whether to patch an existing skill, create a new reusable skill, consolidate knowledge/memory, or take no adaptation action. - Decision owner: the isolated first-party Self-Evolution review Agent/model actor. - Supporting / enforcement mechanisms: idle trigger thresholds, restricted evolution toolset, guarded workspace paths, pre-change backup, snapshot diff/change detection, transactional rollback and evolution records. - Closure path: the review Agent senses conversation-derived external signals, selects and writes an adaptation, the executor commits only real guarded changes, and later normal Agent runs load/use the revised skill/knowledge/persona state; if no clear signal exists it explicitly leaves capability unchanged. - Boundary reachability: Self-Evolution is started by normal AgentBridge initialization, its configuration class defaults enabled, and the standard pinned config-template.json ships selfevolutionenabled: true; the decision actor is therefore reachable in the supported distribution without borrowing a dogfood or contributor agent. - Why this is / is not agent-owned: trigger timing, backups and write guards are deterministic support, but the model review Agent owns the discretionary judgment of whether a past external interaction predicts future reusable need and which permitted adaptation to make. - Evidence: pinned agent/evolution/config.py, trigger.py, executor.py, prompts.py, bridge/agentbridge.py, config-template.json and docs/memory/self-evolution.mdx. - Basis: explicit and structural. - Confidence: high. - Caveats: simple memory consolidation alone is not the credited S4 witness. The positive mapping relies on the separately evidenced prospective skill-adaptation path: detecting a workflow likely to be wanted again or a skill defect exposed in use, autonomously generating an adaptation, and returning that change into later capability. - External distinction: the review consumes user conversation and actual skill/task experience from the environment, including repeated preferences, failures and emergent workflows. - Future / prospective distinction: the evolution prompt explicitly asks whether a workflow is reusable and likely to be wanted again, and documentation defines the goal as creating/fixing skills so they can be reused next time and future conversations improve. - Adaptation option generated: patch a defective skill, encode an emergent workflow as a new reusable skill, consolidate durable knowledge/memory, complete suitable unfinished work, or deliberately make no change. - Path back into current capability / S3: committed workspace/skill/knowledge changes are the same first-party artifacts read by subsequent normal Agent operation; operator rollback remains a separate parent intervention path rather than the owner of the autonomous adaptation judgment.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S5 / identity: - State: A(P) - Function: govern the Agent&#39;s durable identity/personality and highest-level workspace behavioral principles through first-party identity files that are loaded into subsequent system prompts. - Disturbance / variety regulated: drift between the Agent&#39;s durable identity/behavioral principles and explicit repeated signals about what the assistant should be, plus explicit operator decisions to redefine those identity/policy artifacts. - Decisive decision or feedback right: in the autonomous mode, decide whether an explicit repeated identity/personality/style signal is strong enough to justify a bounded AGENT.md identity revision; in the parent mode, authoritatively edit AGENT.md/RULE.md through the authenticated core-file administration surface. - Decision owner: base mode — the isolated Self-Evolution review Agent for the deliberately narrow autonomous identity-evolution decision; parent mode — the authenticated self-hosted operator as ultimate authority over the installation&#39;s core identity/policy files. - Supporting / enforcement mechanisms: evolution signal criteria and guarded writes/backups; AgentAdminService core-file revision checks and atomic writes; authenticated Web endpoint; prompt/workspace loader; targeted runtime eviction after operator edits. - Closure path: autonomous mode: repeated identity-level external signal → review-Agent identity judgment → guarded AGENT.md edit → subsequent runtime loads the changed persona. Parent mode: authenticated operator reads/edits a core identity/policy file → atomic persistence and cached-Agent eviction → subsequent Agent instance reloads that file into its system prompt. - Boundary reachability: both modes are shipped supported runtime paths: default-enabled Self-Evolution may edit AGENT.md under its standard guard, while the authenticated Web Agents API exposes core-file read/write and immediately evicts the changed runtime. - Why this is / is not agent-owned: the base identity change is not a static prompt or automatic parser; the review Agent must judge whether a rare explicit repeated signal warrants changing its own identity artifact. The separate operator mode retains parent authority to set or override the same identity/policy surface, hence A(P) rather than plain A. - Evidence: pinned agent/evolution/prompts.py, executor.py, agent/prompt/workspace.py, agent/prompt/builder.py, agent/admin.py and channel/web/api/agents.py. - Basis: explicit and structural. - Confidence: medium-high. - Caveats: ordinary permission settings, tool approvals, memory/preferences and per-task steering are not credited as S5. The autonomous claim is narrowly limited to the explicit first-party AGENT.md identity-evolution path; operator edits establish the separate parent mode. - Identity / ultimate-policy issue: AGENT.md is explicitly defined by the shipped templates as the Agent&#39;s identity/personality and is loaded with RULE.md into the system-prompt context; this is materially different from ordinary task or tool policy. - Ultimate authority in each claimed mode: base (A) — Self-Evolution Agent decides whether the standard rare-signal criterion warrants a durable identity edit; parent (P) — authenticated operator directly owns the authoritative core-file edit and may override/undo Agent evolution. - Return-to-operation path: both modes persist the core file used by prompt construction; operator writes additionally evict the cached runtime, and later Agent initialization reloads the changed identity/policy context.\">A(P)</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/a00011ae5e8e9ee62aa713d51f283559f12102d4/assessments/cowagent.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit a00011ae5e8e9ee62aa713d51f283559f12102d4\">a00011a &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-09-16T23:24:44+03:00\"><th scope=\"row\"><a href=\"https://github.com/agno-agi/agno\" target=\"_blank\" rel=\"noopener\">Agno</a><small>2022</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/agno-agi/agno/tree/44219f8532e2fe6ce936850455f4b9a2567e4194\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 44219f8532e2fe6ce936850455f4b9a2567e4194\">44219f8 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: member agents autonomously execute bounded model/tool work and return results.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: TeamMode.tasks provides an out-of-box agent-owned mutual-adjustment loop over a shared task board. The leader assigns ownership, prevents duplicate tasks, encodes dependencies, observes member outcomes and can retry/reassign/change the plan; dependency state prevents conflicting/premature execution. This goes beyond one-shot delegation.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: the same leader has a current whole-team view of tasks, assignees, dependency/blocked state, results and failures, plus authority to create/reprioritize through dependencies, assign/reassign members, execute work, update status and decide overall completion. That is a concrete agent-owned current-control loop over shared operational commitments. Human-in-the-loop paths pause member/tool execution and return the result to the team; they do not independently take ownership of the team-level assignment/plan/completion right, so no separate (P) mode is published.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: Agno lets applications compose reviewer/critic members, but the standard team runtime does not supply a distinct sufficiently independent audit channel with alternative operational access and required corrective closure.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: memory, knowledge, reasoning and learning capabilities can improve team operation but do not by themselves instantiate a distinct external-and-prospective intelligence function coupled against S3.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: team role, instructions, permissions, approvals and identity are application/parent configured. The tasks leader regulates execution but is not given ultimate agent-owned policy/identity authority or an S3–S4 closure role.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/9ee1ea7472777767928c8b2ab035e0948a0467e9/assessments/agno.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 9ee1ea7472777767928c8b2ab035e0948a0467e9\">9ee1ea7 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"1\" data-assessment-at=\"2026-11-24T14:21:35Z\"><th scope=\"row\"><a href=\"https://github.com/parlant/harness\" target=\"_blank\" rel=\"noopener\">H</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-24\">2026-11-24</time></td><td class=\"review-ref\"><a href=\"https://github.com/parlant/harness/tree/a45a50835d9fc51712a3afe0a2f97e8970781a0e\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision a45a50835d9fc51712a3afe0a2f97e8970781a0e\">a45a508 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Execute coding sessions against workspace, using model-selected shell/filesystem tools and subsequent feedback. - Disturbance / variety regulated: Unknown repository state and task/tool failures. - Decisive decision or feedback right: Choose and revise tool actions and completion. - Decision owner: Real model-backed coding session. - Supporting / enforcement mechanisms: OTP coordinator, provider stream, tool workers, persistence and retry. - Closure path: Generation emits tool calls, committed results return to next model turn, model returns terminal response. - Boundary reachability: Default coding harness tools and ReqLLM generation are packaged with daemon; no client attachment required. - Why this is / is not agent-owned: Removing model leaves transport and state but no task-level discretionary choice. - Evidence: lib/h/harness/coding.ex, lib/h/session/server/generation.ex, lib/h/session/server/tools.ex, lib/h/provider/reqllm.ex - Basis: explicit -\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: - State: A - Function: Attenuate conflicting writes among coding sessions by selectable isolated workspaces or read-only child roles, backed by writer leases. - Disturbance / variety regulated: Parallel parent/child or sibling sessions competing for writes to the same canonical cwd. - Decisive decision or feedback right: Root model chooses child read-only role or distinct prepared worktree, then responds to returned child receipts/outcomes. - Decision owner: Root model owns isolation/role choice; deterministic lease manager enforces same-workspace exclusion. - Supporting / enforcement mechanisms: Subagent schema, child cwd and read-only restrictions, WorkspaceLease waiter/handoff, durable settlements. - Closure path: Children operate under selected workspace/tool constraints; mutating calls wait for lease, resume on grant; child results return to caller. - Boundary reachability: Default depth-gated subagent exposes cwd/readonly and bash to prepare worktrees; daemon dispatch and writer lease are shipped. - Why this is / is not agent-owned: Model chooses separation in response to actual work; deterministic manager serializes same-workspace writes, without owning discretionary choices. - Evidence: lib/h/tools/subagent.ex, lib/h/session/subagents.ex, lib/h/workspacelease.ex, lib/h/workspacelease.ex, lib/h/session/server/workspacewait.ex, docs/architecture/subagents.md - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S3 / regulation: - State: P - Function: Owner regulates current commitments across daemon sessions using catalog state and targeted stop/lease handoff. - Disturbance / variety regulated: Concurrent operating sessions, contested workspace and conflicting current priorities. - Decisive decision or feedback right: Choose which current commitment to stop or prioritize for workspace allocation. - Decision owner: Authenticated daemon owner at the daemon-wide recursion. - Supporting / enforcement mechanisms: Live catalog, stop-session commands, holder identification and lease-fenced cancellation/handoff. - Closure path: Owner selects stop holder; waiting session prioritised, holder cancellation commits, lease released and waiter resumes. - Boundary reachability: Owner web inbox plus session workspace-wait controls invoke first-party command path; no custom composition. - Why this is / is not agent-owned: Autonomous root can steer/abort its own children but no shipped model with daemon-wide operating authority/view; owner has all-session view and decides exception. Fixed queue/account policy is support, not agent ownership. - Evidence: clients/web/lib/hweb/live/inboxlive.ex, clients/web/lib/hweb/live/sessionlive.html.heex, lib/h/session/server/workspacewait.ex, lib/h/workspacelease.ex, lib/h/session/server/commands.ex, lib/h/session/subagents.ex - Basis: explicit/structural - Confidence: medium - Caveats: Only daemon-owner current control; a root subtree has narrower agent steering rights. No A or C mode for autonomous daemon-wide controller inferred from generic owner API.\">P</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3* / direct audit: - State: C - Function: Expose separate artifact review channel to challenge coding session output against raw worktree or pinned Git blobs, with source-bound findings returned to session. - Disturbance / variety regulated: Unreliable self-reported coding outcome or incorrect changes. - Decisive decision or feedback right: Choose independently which evidence to inspect and what corrective findings to return. - Decision owner: Owner reviewer or composed autonomous reviewer; shipped model audit decision actor not established. - Supporting / enforcement mechanisms: Review file and commit API, raw Git reads, revision-bound selection and comment submission. - Closure path: Owner reviewer reads actual changed files/commit and sends anchored ask/note to the target conversation; composed independent model reviewer can use review APIs and return findings. - Boundary reachability: First-party web review and daemon review APIs are available alongside ordinary session runtime. - Why this is / is not agent-owned: Producing coding model does not determine what raw bytes the separate reviewer inspects or what findings are submitted; autonomy needs reviewer composition. - Evidence: lib/h/daemon/review.ex, clients/web/lib/hweb/live/reviewlive.ex, lib/h/daemon.ex, docs/architecture.md - Basis: structural - Confidence: medium - Caveats: No mandatory independent reviewer, no proof of reviewer competence; review may be performed by owner or composed agent. Ordinary subagent delegation alone not credited.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No demonstrated prospective external adaptation loop at daemon boundary. - Disturbance / variety regulated: Future shifts in model/provider/environment capabilities. - Decisive decision or feedback right: No returned adaptation judgment from prospective external sensing. - Decision owner: None established. - Supporting / enforcement mechanisms: Curated model catalog, user provider config, external usage polls in optional MultiCodex, context compaction. - Closure path: Account observations select present eligible route; provider edits affect configuration but no first-party prospective option-generation loop. - Why this is / is not agent-owned: Quota polling is present resource regulation; user-entered catalog and model picker are configuration, not external-and-future intelligence. - Evidence: lib/h/provider/reqllm/catalog.ex, docs/providers.md, extensions/multicodex/README.md, docs/architecture.md - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No runtime ultimate-policy closure at daemon-wide boundary. - Disturbance / variety regulated: Potential disputes over daemon purpose/ultimate policy. - Decisive decision or feedback right: No first-party identity-level resolution right evidenced. - Decision owner: Owner configures accounts, instructions and provider settings, not established S5 path. - Supporting / enforcement mechanisms: Owner authentication, config, instructions and tool selection, extension settings. - Closure path: Config changes govern subsequent requests but no identity/policy matter routed to ultimate authority and returned as such. - Why this is / is not agent-owned: Owner controls local tool/config boundaries, but ordinary configuration and task steering are not ultimate policy arbitration. - Evidence: lib/h/harness/coding.ex, docs/providers.md, docs/extensions.md, docs/architecture.md - Basis: structural -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/591cf5404a731452a36d1b840ba1c5fbd5f23a54/assessments/h/h.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 591cf5404a731452a36d1b840ba1c5fbd5f23a54\">591cf54 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-11-24T13:57:26Z\"><th scope=\"row\"><a href=\"https://github.com/dmoka/mini-harness\" target=\"_blank\" rel=\"noopener\">mini-harness</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-24\">2026-11-24</time></td><td class=\"review-ref\"><a href=\"https://github.com/dmoka/mini-harness/tree/4563935c87c4e22514a6ee3842fc51fc34ebe2fb\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 4563935c87c4e22514a6ee3842fc51fc34ebe2fb\">4563935 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: produce requested repository investigation and changes. - Disturbance / variety regulated: uncertain repository content, tool errors and incomplete changes. - Decisive decision or feedback right: select and revise tool actions, decide task completion. - Decision owner: model-backed coding agent. - Supporting / enforcement mechanisms: Session, tools, permissions, hooks, transport and shell. - Closure path: results/errors and optional stop-hook rejection enter the next model turn; agent continues or reports completion. - Boundary reachability: main creates Session and calls runloop; both backends return model-selected actions to the same dispatcher. - Why this is / is not agent-owned: removing the model leaves execution machinery but no discretionary action selection or completion. - Evidence: loop, file tools, shell, entrypoint. - Basis: explicit. - Confidence: high. - Caveats: plan mode and restricted commands can require human approval; Stop retries are bounded. No performance claim.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: - State: A - Function: attenuate concurrent coding-cell interference through selectable isolated writable checkouts and joined branch outcomes. - Disturbance / variety regulated: concurrent editing children modifying overlapping files or Git working state. - Decisive decision or feedback right: calling model chooses whether each child gets its own worktree and receives the resulting branch report for subsequent handling. - Decision owner: parent coding agent, while children retain local task discretion. - Supporting / enforcement mechanisms: runsubagent worktree parameter, parallel executor, unique Git branch/worktree creation, child process cwd and join. - Closure path: chosen isolated checkout becomes the child&#39;s operational environment; separate writes avoid same-checkout overwrite; branch/report returns to the parent&#39;s next turn. The isolation loop itself does not require branch merge. - Boundary reachability: runsubagent is a default core tool; model directly chooses worktree=true; concurrent calls launch separate children with selected checkouts. - Why this is / is not agent-owned: the model chooses when to invoke isolation; runtime implements the choice rather than deciding which tasks need it. - Distinct S1 units: concurrent task-specific coding children with own loop, checkout and branch/report deliverable. - Inter-S1 disturbance: editing agents otherwise share a repository working copy and may interfere through concurrent writes. - Attenuating coordination relation: selectable per-child unique Git worktree separates writes while work continues. - Feedback into subsequent S1 behaviour: each child executes in its selected cwd; branch/report returns to next parent turn for further work without concurrent shared-file edits. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the choice explicitly changes concurrent editing cells&#39; environment to isolate writes. - Evidence: fork/join, subagent and worktree, default tools, tests. - Basis: structural. - Confidence: medium. - Caveats: isolation, not proven conflict-free merge or distributed locking. Git merge may require human permission; child commit failure is not fully checked. Context-only mode does not sandbox arbitrary shell commands.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no supplied whole-system current-control loop at the local multi-cell boundary. - Disturbance / variety regulated: potential competition for shared commitments/resources. - Decisive decision or feedback right: not established beyond task-local actions and delegation. - Decision owner: no evidenced S3 owner; human approves specific plans/commands, developer defines static permissions. - Supporting / enforcement mechanisms: tool lists, plan gate, permissions, fork/join and scope. - Closure path: no whole-system current-state intervention over resources/commitments. - Why this is / is not agent-owned: parent receives completed reports and selects subtasks, not whole-system resource bargaining or intervention over active cells; plan approval is task-local. - Evidence: session and join, plan, worktrees, permissions. - Basis: structural. - Confidence: medium. - Caveats: ordinary task management and integration do exist.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no supplied complementary audit loop distinct from ordinary investigation/verification. - Disturbance / variety regulated: potentially unreliable routine coding reports. - Decisive decision or feedback right: no specific independent audit judgment path. - Decision owner: no evidenced S3 owner. - Supporting / enforcement mechanisms: generic fresh-context subagent, file tools, configurable hooks and ordinary tests. - Closure path: subtask reports and configured hook failures return to ordinary task loop; no dedicated complementary challenge is wired. - Why this is / is not agent-owned: generic subagent prompt supplies arbitrary investigation, not complementary audit relation; generic hooks require external audit composition. - Evidence: subagent, fresh-context test, loop, hooks, stop test. - Basis: structural. - Confidence: medium. - Caveats: caller could request audit, or configure external verifier; not a shipped function-specific loop.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no material prospective external adaptation loop. - Disturbance / variety regulated: potential future changes in harness capability/environment. - Decisive decision or feedback right: no future-facing harness adaptation right established. - Decision owner: no evidenced S4 owner. - Supporting / enforcement mechanisms: memory, compaction, planning, model fallback and shell/tools. - Closure path: internal facts/summaries return into later prompts, not external prospective options into capability. - Why this is / is not agent-owned: memory cleanup merges internal notes; fallback and coding the user&#39;s target do not establish harness adaptation. - Evidence: prompt, memory, compaction, plan. - Basis: structural. - Confidence: high. - Caveats: no inference about maintainer roadmap or hypothetical self-editing.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no runtime ultimate-policy or identity-resolution path. - Disturbance / variety regulated: potential conflict over ultimate policy/identity. - Decisive decision or feedback right: no evidenced identity-level decision path. - Decision owner: static developer/user configuration and task-local human permission, not established S5. - Supporting / enforcement mechanisms: BASEPROMPT, AGENTS.md, settings.json, askhuman and plan gate. - Closure path: rules enter prompts and approval changes command/mode, not an ultimate-policy issue returned into operations. - Why this is / is not agent-owned: no concrete identity-level issue reaches an agent or legitimate parent through a shipped closure loop. - Evidence: base prompt, rules, human input, plan, settings. - Basis: structural. - Confidence: high. - Caveats: configuration ownership exists, but no S5 loop; maintainer governance outside recursion.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/38f28a502719ac3fb85de236bceded182a1fc7d3/assessments/dm/dmoka-mini-harness.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 38f28a502719ac3fb85de236bceded182a1fc7d3\">38f28a5 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-11-18T18:11:19+03:00\"><th scope=\"row\"><a href=\"https://github.com/pmndre/pine\" target=\"_blank\" rel=\"noopener\">PINE</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-18\">2026-11-18</time></td><td class=\"review-ref\"><a href=\"https://github.com/pmndre/pine/tree/c9dbfd129a8574459e37cfa834662b0fa8ca8a1b\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision c9dbfd129a8574459e37cfa834662b0fa8ca8a1b\">c9dbfd1 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Carry out event-triggered and requested tasks using model-directed tools and independent agent sessions. - Disturbance / variety regulated: Distinct user objectives, changing external events, file state, model responses and tool results. - Decisive decision or feedback right: Select tools, edits, responses and further tasks from current context. - Decision owner: Installed model-backed agent session, within owner-set access and model constraints. - Supporting / enforcement mechanisms: Task persistence, pi session runtime, source subscriptions, task queue, sandbox and tool gates. - Closure path: Model/tool feedback changes the next action; resulting files, emitted messages and task state persist into future interactions. - Boundary reachability: Standard pine init includes main agent and model session runtime; source events and operator prompts are both wired to the same task submit/execute path. - Why this is / is not agent-owned: The model makes task-level choices; PINE&#39;s deterministic event transport and permissions do not choose the task&#39;s substantive outcome. - Evidence: installed runtime, task submission and model dispatch, run and session loop, source-to-agent event path. - Basis: structural - Confidence: high - Caveats: Requires an actually configured reachable model. No live model task was executed during this source-based review.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: - State: A - Function: Attenuate concurrent operational agents&#39; conflicting edits to the same Git repository. - Disturbance / variety regulated: Simultaneous independent code edits can overwrite each other or conflict when brought back to the common branch. - Decisive decision or feedback right: Initiating agent selects isolated worktree mode for delegated/subagent tasks and then decides how to merge, retry or resolve conflicting branches after receiving results. - Decision owner: Initiating model-backed coding agent in a supported owner-trusted session; runtime only executes Git safety rules. - Supporting / enforcement mechanisms: Independent pine/ branches, worktree allocation, merge-tree checks, no-overwrite merge gates and conflict details returned to the initiating actor. - Closure path: Each child writes to a separate checkout; its returned branch information informs the initiator&#39;s subsequent integration. Merge conflicts identify overlapping files and require resolution before advancing the base. - Boundary reachability: delegate and subagent both expose worktree: true in the standard tools and return branch/merge instructions; the owner control API also offers conflict-aware merge operations. - Why this is / is not agent-owned: The lead can decide whether to isolate, how to integrate and how to revise an overlapping assignment; fixed Git commands merely implement/refuse that decision. - Distinct S1 units: Two agent/subagent tasks with separate model sessions, outputs and worktree branches, working on a shared project. - Inter-S1 disturbance: Concurrent writes to one checkout and divergent edits to the same file during integration. - Attenuating coordination relation: Runtime-enforced independent worktrees and explicit agent-selected merge/integration policy, with a conflict refusal rather than hidden overwrite. - Feedback into subsequent S1 behaviour: Branch return prompts the parent to merge or reassign work; rejected merge names overlapping files and blocks adoption until a revised child operation. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: The shipped worktree/merge subsystem explicitly addresses a concrete inter-worker write collision, including overlap detection and correction feedback. - Evidence: delegation worktree option and child return, parallel subagents, collision intent and isolation, merge conflict refusal, owner merge conflict return. - Basis: structural - Confidence: medium - Caveats: Isolation is optional and only source-proven; coordination of arbitrary separate non-code agents is not established. The base merge is not guaranteed to succeed; successful conflict resolution is actor-dependent.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S3 / regulation: - State: P - Function: Parent/operator current-control oversight of active agents and competing runtime capacity. - Disturbance / variety regulated: Multiple sessions and workers compete for execution slots and may continue a task that the owner no longer wants. - Decisive decision or feedback right: View installation-wide tasks, intervene with task cancellation, set agent execution mode and choose global concurrent-run capacity. - Decision owner: Authenticated installation owner through the bundled API/CLI/TUI. - Supporting / enforcement mechanisms: Global status and task listing, task cancellation, persisted model/mode limits and concurrency limiter. - Closure path: A canceled task stops/aborts subsequent execution; owner-selected per-agent mode affects later tool authorization; changed concurrency capacity governs scheduling after restart where documented. - Boundary reachability: The standard HTTP control API exposes /status, /tasks, /agents, /tasks/&lt;id&gt;/cancel, agent mode updates and global limits.maxConcurrentRuns configuration. - Why this is / is not agent-owned: The whole-installation intervention right belongs to the local owner, not the model or deterministic limiter; model-managed delegation is task-local. - Whole-system current view: The standard /status, /tasks and /agents endpoints expose work across agents rather than only one child&#39;s task status. - Current-control decision scope: Cancel a particular run, change an agent&#39;s operating mode, or choose available parallel execution slots. - Evidence: global listing, task stop and agent mode, cancellation endpoint, global concurrency parameter, runtime scheduling. - Basis: structural - Confidence: medium - Caveats: maxConcurrentRuns is a saved-next-start setting, not immediate preemption; no autonomous whole-installation S3 decision is credited. Simple human approvals for individual tool actions are not counted as S3.\">P</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: A sufficiently independent corrective audit of operational claims, beyond routine checks, was not established in the shipped installation. - Disturbance / variety regulated: A working agent may incorrectly report completion of a goal or of a delegated task. - Decisive decision or feedback right: The goal-mode judge issues MET/CONTINUE/BLOCKED from the agent&#39;s answer, not an independent review of changed files or external effects. - Decision owner: Goal status continuation belongs to judge/runtime; it does not own an independent evidence-based complementary audit. - Supporting / enforcement mechanisms: Goal judge prompt, runtime status, optional parallel tasks and owner review. - Closure path: A judge verdict can cause another goal round, but its information source is the producer&#39;s own report. No independent raw-evidence audit decision/return loop was identified. - Why this is / is not agent-owned: A second model call on the producer&#39;s answer is not an independent access path to operational reality; a user-created reviewer is not automatically present in the standard distribution. - Evidence: judge&#39;s exact input, judge and continuation, generic subagent, not an audit. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No shipped prospective environmental-intelligence-to-capability-adaptation loop was established for the PINE installation itself. - Disturbance / variety regulated: New external event types, model availability and future demands may motivate changing what agents can do. - Decisive decision or feedback right: Owners can ask the main agent to install sources, routes or agents; no first-party S4 decision loop was found that turns external future-relevant distinctions into options and subsequently changes current capability. - Decision owner: Owner controls explicit changes to topology and configuration; individual agents respond to subscribed events in their current jobs. - Supporting / enforcement mechanisms: General-purpose source subscriptions, model/manual lookups, routed events, agent creation and administrator tools. - Closure path: A source event can wake an agent and an owner-requested configuration change can affect later operations, but the inspected standard flow does not link those steps into a prospective adaptation judgment. - Why this is / is not agent-owned: Environmental reaction and ordinary runtime self-configuration are not by themselves a demonstrated future-oriented intelligence function. - Evidence: source subscription lifecycle, router event handling, agent construction needs owner request/approval, goal loop is owner-objective continuation. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S5 / identity: - State: P - Function: Set and revise installation-wide normative identity/behavior rules that govern all agents. - Disturbance / variety regulated: Divergent agent-specific behaviors and revised owner requirements for the whole installed organization. - Decisive decision or feedback right: Decide what collective rules, traits and behavioral obligations should hold for every installed agent. - Decision owner: The installation owner, acting as legitimate parent through explicit instructions or authenticated global-instruction control. - Supporting / enforcement mechanisms: Shared AGENTS.md read into every agent&#39;s prompt, exclusive main-agent edit tooling and authenticated owner shared-file API. - Closure path: Owner supplies an installation-wide policy decision; the main agent/owner writes the global rule file; subsequently agents read that file on their next message, changing their governed behavior. - Boundary reachability: The installed default main agent is explicitly charged with maintaining shared rules; all agents load shared instruction files and the owner API can edit them without creating a custom plugin. - Why this is / is not agent-owned: The main agent transcribes/implements owner-decided normative rules, but cannot legitimately substitute its own ultimate policy for the owner&#39;s. - Identity / ultimate-policy issue: Which binding behavioral rules and common agent identity/ethos should apply across all agent cells, not whether to approve a particular tool call. - Ultimate authority in each claimed mode: Authenticated owner only; no independent autonomous S5 closure claimed. - Return-to-operation path: Authenticated owner/main-agent shared-file update → saved global AGENTS.md → next-session prompt update for every agent → subsequent behavior under revised collective rules. - Evidence: global rules and owner write rights, global instruction incorporation, authenticated shared-file update, main agent&#39;s delegated role. - Basis: structural - Confidence: medium - Caveats: A simple per-tool permission is not S5. Credit is strictly to owner-decided collective normative policy changes; no automated S3–S4 strategic settlement or autonomous policy-maker is demonstrated.\">P</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/d6c36e01efe4a6adb1a4176eb2f7a18b57c56d0f/assessments/pi/pine.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit d6c36e01efe4a6adb1a4176eb2f7a18b57c56d0f\">d6c36e0 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"2\" data-assessment-at=\"2026-11-18T18:41:35+03:00\"><th scope=\"row\"><a href=\"https://github.com/yuzhiyang1/weora\" target=\"_blank\" rel=\"noopener\">Weora</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>2</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-18\">2026-11-18</time></td><td class=\"review-ref\"><a href=\"https://github.com/yuzhiyang1/weora/tree/b860b68d1aeff13d0b90394d3468bc9c60eff456\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision b860b68d1aeff13d0b90394d3468bc9c60eff456\">b860b68 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Perform substantive authorized agent changes and incident work under a persisted task mandate. - Disturbance / variety regulated: Changing user objectives, code/repository environment, model/tool results, tests and follow-up messages. - Decisive decision or feedback right: Configured worker agent chooses plan and authorized code/task actions through a native Pi session, and produces changed workspace/test/delivery evidence. - Decision owner: First-party configured Weora worker agent under shipped worker runtime; Pi model runtime is a separately installed adapter, not an independent credited organization. - Supporting / enforcement mechanisms: RunService, agent version/context, credential-authorized project sources, execution leases, sandbox tools, task/worker run events, continuation and code delivery. - Closure path: User task and approved scope to worker model turn, tool execution under grants to saved changes and reports, test/diff or delivery receipt to task and later follow-up. - Boundary reachability: Shipped backend code and APIs support this configured self-hosted mode with authorized owner, model runtime and workers. - Why this is / is not agent-owned: Without model-directed worker there is no substantive answer/edit decision; the deterministic scheduler merely reserves and invokes it. - Evidence: backend/src/weora/modules/runs/application/execution.py, backend/src/weora/modules/coordination/workerruntime.py, backend/src/weora/modules/delivery/application/service.py, README.md - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: Attenuate interference from simultaneous worker/task claims on shared objectives and incoming team instructions. - Disturbance / variety regulated: Independent workers or incoming threads may initiate duplicate effort, cross-owner task routing and overlapping work. - Decisive decision or feedback right: First-party coordination can select whether a request belongs to an existing task, stop/attach it instead of launching a competing new worker; actual inter-worker conflict adjudication needs an installed team configuration. - Decision owner: Composed main-session coordinator plus separately configured worker/task cells; source supports the decision, but concrete S1-vs-S1 interference scenario was not executed. - Supporting / enforcement mechanisms: Owner matching, single-task assignment, ticket mandates, canonical decision atomicity, source/author isolation, effect leases and worker dispatch. - Closure path: Overlapping work request → coordinator assesses existing ticket ownership and may attach/stop or accept one scoped task → decision persisted and worker gets the new input or no duplicate worker created. - Boundary reachability: Shipped backend code and APIs support this configured self-hosted mode with authorized owner, model runtime and workers. - Why this is / is not agent-owned: Not merely an at-least-once queue: main-session model has an explicit attach/accept/stop choice and an existing owner guard, although only constructor-grade conflict closure is evidenced. - Evidence: backend/src/weora/modules/coordination/engine.py, backend/src/weora/modules/coordination/mainsession.py, backend/src/weora/modules/coordination/workerdispatch.py - Basis: structural - Confidence: moderate - Caveats: Exact pinned-source/static code analysis, without external Pi/cloud credentials or live model execution. - Distinct S1 units: Separately assigned task/worker agents in one configured workspace. - Inter-S1 disturbance: Duplicate or overlapping incoming objectives can send two workers after the same work, or route new instructions to the wrong current worker. - Attenuating coordination relation: The model coordinator classifies accept/attach/stop and source identity; the state engine prevents fresh competing acceptance when an existing task owner holds it. - Feedback into subsequent S1 behaviour: Atomic decision either attaches new input to the existing ticket/worker, stops a ticket, or dispatches one new authorized worker with frozen scope. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: A constructible inter-worker duplicate-work/ownership attenuator is present, but not proven fully autonomous under a live cross-worker disturbance.\">C</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A(P) - Function: Regulate current workspace task commitments, pending worker attention, stop/retry/continuation and authorized work. - Disturbance / variety regulated: Pending or failed workers, changing human instructions, duplicate claims, unresolved attention and revoked access. - Decisive decision or feedback right: Main coordinator chooses accept/attach/stop/resume/requeue based on current workspace state, while authorized user/admin may pause scopes, stop work or decide approval boundaries. - Decision owner: Model-driven main-session coordinator in configured base mode; human workspace/task authority in parent mode. - Supporting / enforcement mechanisms: Main-session reads authorized state, current tickets/effects, assignment reports and notices; engine validates decisions and persists leases/status; UI/APIs expose task status and owner actions. - Closure path: Current ticket and worker reports → coordinator model decision → engine applies verified current task control → next worker assignment/input/resume or user hold; parent overrides access/stop/pause and the next worker honors it. - Boundary reachability: Shipped backend code and APIs support this configured self-hosted mode with authorized owner, model runtime and workers. - Why this is / is not agent-owned: A model makes actual disposition choices over whole scoped workload in main-session, while deterministic code checks leases and mandate. Parent choices are binding through exposed config/permission and run APIs. - Evidence: backend/src/weora/modules/coordination/mainsession.py, backend/src/weora/modules/coordination/engine.py, backend/src/weora/modules/coordination/service.py, backend/src/weora/modules/runs/application/service.py - Basis: structural - Confidence: moderate - Caveats: Exact pinned-source/static code analysis, without external Pi/cloud credentials or live model execution. - Whole-system current view: Scoped main coordinator reads authorized triggers, tickets, active worker assignments, unresolved human/peer inputs and effects within one project route. - Current-control decision scope: Accept/attach/stop/resume current objectives, choose when a worker may receive work, persist attention/wait and route completed/partial reports; human can revoke authorization/stop/pause work.\">A(P)</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3* / direct audit: - State: C - Function: Supplement worker claims with directly inspectable test outputs, code diffs and delivery receipts under a distinct human review. - Disturbance / variety regulated: Worker may assert successful task completion without current source/tests or authorization. - Decisive decision or feedback right: An authorized human can inspect recorded sandbox test output and branch diff independent of agent summary, then authorize or demand another run; full independent default audit actor is not bundled. - Decision owner: Constructed independent human/source reviewer, not the worker that generated the report. - Supporting / enforcement mechanisms: Sandbox test execution and code-host review artifacts, receipt APIs, run event stream and user follow-up/approval path. - Closure path: Worker report → independent source/test evidence view → user review or new directed task → follow-up run alters next task operation; source-level proof is configurable. - Boundary reachability: Shipped backend code and APIs support this configured self-hosted mode with authorized owner, model runtime and workers. - Why this is / is not agent-owned: The evidence originates from executed tests/source changes that can be checked outside the worker&#39;s self-report, rather than an LLM summary; independent audit is not default runtime autonomy. - Evidence: backend/src/weora/modules/delivery/application/service.py, backend/src/weora/modules/delivery/infrastructure/github.py, backend/src/weora/modules/runs/application/service.py, README.md - Basis: structural - Confidence: moderate - Caveats: Exact pinned-source/static code analysis, without external Pi/cloud credentials or live model execution. - Claim being audited: Worker claim of passing tests, completed change and valid delivery. - Ordinary reporting path: Worker status/report and task event feed. - Complementary access path: User can inspect actual saved test output and versioned code diffs/PR artifact through sandbox and code-hosting integration. - Independence boundary: Human source reviewer can use direct delivery/test evidence, distinct from model-authored report; first-party tools enforce source grants. - Who acts on findings: User approves, rejects or issues a specific follow-up requiring a new worker run.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-unknown\" title=\"S4 / adaptation: - State: ? - Function: Turn external future changes and review feedback into durable change of Weora agent capability. - Disturbance / variety regulated: Evolving model performance, new skills and external team requirements. - Decisive decision or feedback right: Human may select new agent version, skills and model configuration; a supported complete function-specific future-intelligence/option/return loop is not demonstrated. - Decision owner: Potential workspace owner through agent registry, not a verified autonomous S4 decision maker. - Supporting / enforcement mechanisms: Agent/version registry, skill sharing, model catalog and user settings; roadmap lists planned long-term memory/schedules. - Closure path: Capability/config changes can be saved and used on later runs, but external future signal → evaluated adaptation options → returned decision with tested future capability effect is unestablished. - Boundary reachability: Shipped backend code and APIs support this configured self-hosted mode with authorized owner, model runtime and workers. - Why this is / is not agent-owned: The repo ships configuration persistence but not a demonstrated prospective analysis loop; planned memory/RAG/schedules are explicitly excluded. - Evidence: backend/src/weora/modules/agents/application/service.py, backend/src/weora/modules/consolesettings/service.py, README.md - Basis: structural -\">?</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S5 / identity: - State: P - Function: Maintain legitimate workspace purpose and permitted agent identity, authorization and execution rights. - Disturbance / variety regulated: Unauthorized repository or Feishu inputs, version changes, unapproved writes, model credential abuse and scope expansion. - Decisive decision or feedback right: Human workspace owner sets agent versions, source grants, runtime/connection choices and approves scoped plans before worker tools can act. - Decision owner: Legitimate member/administrator at workspace recursion; model coordinators cannot invent or expand grants. - Supporting / enforcement mechanisms: Authorized context and access checks, agent registry versions, route grants, main coordination policy, worker mandate checks and tool gateway. - Closure path: Human policy/authorization → persisted workspace grants and agent/runtime version → repeated lease-time authorization checks → permitted or refused worker operation. - Boundary reachability: Shipped backend code and APIs support this configured self-hosted mode with authorized owner, model runtime and workers. - Why this is / is not agent-owned: Models can propose and route within approved scope, but cannot become the ultimate owner of access or task mandate. - Evidence: backend/src/weora/modules/coordination/service.py, backend/src/weora/modules/coordination/engine.py, backend/src/weora/modules/agents/application/service.py, backend/src/weora/modules/runs/application/execution.py - Basis: structural - Confidence: moderate - Caveats: Exact pinned-source/static code analysis, without external Pi/cloud credentials or live model execution. - Identity / ultimate-policy issue: Which agents, source permissions, repository actions, model resources and approved task scopes are legitimate for this workspace. - Ultimate authority in each claimed mode: Authorized human workspace/project owner; the coordinator and worker run under frozen mandates. - Return-to-operation path: Saved scope/config and version/grant settings are checked by the coordinator and each worker/continuation before tools execute.\">P</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/65cdcc079394ae5e3ab5f530ba935aef190de60a/assessments/we/weora.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 65cdcc079394ae5e3ab5f530ba935aef190de60a\">65cdcc0 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-11-11T17:41:35+03:00\"><th scope=\"row\"><a href=\"https://github.com/kuLm1Fs/lumak-ts\" target=\"_blank\" rel=\"noopener\">LumaK</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-11\">2026-11-11</time></td><td class=\"review-ref\"><a href=\"https://github.com/kuLm1Fs/lumak-ts/tree/ef1d2ddb16630e537c205fadb11031ba7bae6131\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision ef1d2ddb16630e537c205fadb11031ba7bae6131\">ef1d2dd &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Use workspace tools to answer a coding task and, when authorized, change code. - Disturbance / variety regulated: Ambiguous user goals, workspace state, tool errors, context pressure and permission decisions. - Decisive decision or feedback right: Select navigation, file/tool actions, delegation and revisions in response to observed results. - Decision owner: The active model-backed Agent owns the semantic tool and revision choices. Operator permission constrains certain actions. - Supporting / enforcement mechanisms: WorkspaceGuard, provider adapters, tool registry, dedup cache, role modes, session store and traces. - Closure path: Task → model request → selected workspace tool → result or denial enters messages → subsequent action or terminal answer. - Boundary reachability: CLI, embedded TUI and gateway instantiate Agent. Supported auto mode permits the loop to choose and apply local edits within the workspace. - Why this is / is not agent-owned: Choosing the next investigation or edit is model-owned. The runtime constrains and executes those choices. - Evidence: apps/cli/src/commands/chat.ts, packages/core/src/agent.ts, packages/core/src/runtime/loop.ts, packages/core/src/runtime/tool-call.ts, packages/core/src/providers/factory.ts - Basis: Pinned first-party source and declared distribution. - Confidence: High for the bounded structural finding. - Caveats: Source-static assessment. Provider behavior and real-world quality were not tested.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: No distinct response to lateral interference between independent coding units is established. - Disturbance / variety regulated: Concurrent children can share a workspace and issue overlapping operations. - Decisive decision or feedback right: Observe an actual cross-child conflict and coordinate a subsequent change in both affected operations. - Decision owner: Main model delegates tasks; the runtime executes child calls concurrently and joins results. - Supporting / enforcement mechanisms: Promise.all, parent permission ceiling, read-only roles and per-call tool execution. - Closure path: Children return outcomes to the parent. The shipped scheduling relation does not bind sibling conflict detection and adaptive redistribution. - Boundary reachability: Agent registry supplies the delegate tool. Child loops have no recursive delegate path. - Why this is / is not agent-owned: Delegation, capability limits and a final join support the parent task without defining a lateral conflict-resolution loop. - Evidence: packages/core/src/runtime/loop.ts, packages/core/src/runtime/delegate.ts, packages/core/src/runtime/permissions.ts - Basis: Pinned first-party source and declared distribution. - Confidence: High for the bounded structural finding. - Caveats: Source-static assessment. Provider behavior and real-world quality were not tested.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: No whole-system current-control mode is established across coding sessions. - Disturbance / variety regulated: Active session errors, tool requests, workspace selection and availability. - Decisive decision or feedback right: Intervene in whole-system resource commitments using a current operating view and returned decision. - Decision owner: Operator governs a local session and tools. The primary agent delegates its own work. - Supporting / enforcement mechanisms: Gateway conversation and trace views, approval prompts, loop limits and cancellation. - Closure path: Approvals or changed modes affect specific calls or sessions. - Boundary reachability: Gateway supports session and project state operations, while Agent handles each turn. - Why this is / is not agent-owned: Current workspace and per-call permissions do not form a portfolio-control decision or feedback relation. - Evidence: packages/gateway/src/server.ts, packages/gateway/src/state.ts, packages/gateway/src/chat.ts, packages/core/src/runtime/permissions.ts - Basis: Pinned first-party source and declared distribution. - Confidence: High for the bounded structural finding. - Caveats: Source-static assessment. Provider behavior and real-world quality were not tested.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: Complement the producing agent&#39;s own work report with a separate read-only inspection of code changes. - Disturbance / variety regulated: Latent implementation defects or gaps that remain after the producing agent&#39;s own tool feedback. - Decisive decision or feedback right: Inspect the target files and judge whether the implementation contains issues worth correction. - Decision owner: The separately instantiated reviewer model makes the review judgment. The parent model decides whether and how to revise. - Supporting / enforcement mechanisms: Built-in delegate tool, reviewer-specific prompt, role-bound read-only tools, shared workspace and returned DelegateReport. - Closure path: Primary model delegates review → fresh reviewer reads source files and reports → answer is appended as a tool result → parent model may edit or report in its next step. - Boundary reachability: Default Agent registry mounts delegate; auto permits invocation and approve can permit it. The reviewer prompt is shipped by the core prepack configuration. - Why this is / is not agent-owned: The child chooses its own read actions and findings in a fresh review context. The parent cannot substitute its own work report for that separate tool-backed review within this path. - Claim being audited: Whether selected existing code or recent edits fulfill the implementation intent without defects relevant to the delegated review. - Ordinary reporting path: The primary session observes its edit results, tool outcomes and its own response. - Complementary access path: The role-specific child can read and search the shared workspace directly, with a fresh prompt and without edit permissions. - Independence boundary: Separate child loop and prompt with read-only access. It uses the same configured provider and filesystem, and the parent chooses scope and contextual framing. - Who acts on findings: The primary model reads the returned reviewer answer and can adjust implementation or report findings. The harness does not mandate review or enforce a verdict. - Evidence: packages/core/src/agent.ts, packages/core/src/runtime/delegate.ts, packages/core/src/runtime/prompts.ts, packages/core/src/runtime/permissions.ts, packages/core/src/runtime/loop.ts, packages/core/package.json, prompts/subagent-reviewer.md - Basis: Pinned first-party source and declared distribution. - Confidence: High for reachability and separate artifact access; medium for practical independence under shared provider and parent-selected scope. - Caveats: Conditional on a reviewer call with suitable tools and a code artifact to inspect. Static source demonstrates the corrective return path, not measured effectiveness or mandatory remediation.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No prospective capability adaptation is established. - Disturbance / variety regulated: Workspace changes, context overflow and availability of existing skills or provider tools. - Decisive decision or feedback right: Observe future environmental change and select a durable adaptation returned to current capability. - Decision owner: The operator supplies skill files and provider configuration; the runtime selects available inputs for the current task. - Supporting / enforcement mechanisms: Skills selector, context truncation, optional MCP and persisted session memory. - Closure path: A matching skill or retrieved context alters the current prompt. - Boundary reachability: Built-in skill matching, session resume and provider selection are reachable. - Why this is / is not agent-owned: Selecting stored guidance and reacting to current input are local operational behaviors. - Evidence: packages/core/src/runtime/loop.ts, packages/core/src/skills/selector.ts, packages/core/src/skills/store.ts, packages/core/src/runtime/session.ts - Basis: Pinned first-party source and declared distribution. - Confidence: High for the bounded structural finding. - Caveats: Source-static assessment. Provider behavior and real-world quality were not tested.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No ultimate identity or policy arbitration is established. - Disturbance / variety regulated: Current tool permissions and configured role boundaries. - Decisive decision or feedback right: Arbitrate system mandate or ultimate policy and return a binding decision. - Decision owner: The operator sets the tool mode and workspace; developer-defined role rules enforce limits. - Supporting / enforcement mechanisms: CLI modes, approval gates and child permission ceiling. - Closure path: Per-action approval and policy selection change what may run in the current session. - Boundary reachability: Explicit CLI/Gateway approval and plan modes are shipped. - Why this is / is not agent-owned: User consent to an action and a constructor policy do not establish a first-party ultimate identity decision process. - Evidence: apps/cli/src/commands/chat.ts, packages/gateway/src/chat.ts, packages/core/src/runtime/permissions.ts, packages/core/src/runtime/delegate.ts - Basis: Pinned first-party source and declared distribution. - Confidence: High for the bounded structural finding. - Caveats: Source-static assessment. Provider behavior and real-world quality were not tested.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/b29fcd0709bdf141f7b15f579d4f05a57ad585ff/assessments/lu/lumak.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit b29fcd0709bdf141f7b15f579d4f05a57ad585ff\">b29fcd0 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-11-08T15:12:56+03:00\"><th scope=\"row\"><a href=\"https://github.com/chenofchina/onion-harness\" target=\"_blank\" rel=\"noopener\">Onion Harness</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-08\">2026-11-08</time></td><td class=\"review-ref\"><a href=\"https://github.com/chenofchina/onion-harness/tree/dc2be116eddad9c45018d0d8590fa6cc96387bfe\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision dc2be116eddad9c45018d0d8590fa6cc96387bfe\">dc2be11 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: first-party hosted model agents interpret user tasks and perform tool or deliberative work in local environments. - Disturbance / variety regulated: changing user goals, tool results, file/task conditions and differing model-seat arguments. - Decisive decision or feedback right: model-backed agent chooses next task-level action/tool call or substantive seat reply/rebuttal from prompt and feedback. - Decision owner: model-backed agent actor in normal mode; individual seat agents in Roundtable. The deterministic Onion application and external engine transport the choice. - Supporting / enforcement mechanisms: EngineLoop, provider adapters, executor registry, sandbox, Plan/Standard/Strict mode, approvals, memory, task events and configured ceilings. - Closure path: agent-selected call reaches an Onion executor, tool result returns to engine context for further agent choice; Roundtable seat replies enter the shared transcript and later rounds/final consensus. - Boundary reachability: OnionRuntime.runtask wires live tools/options into EngineLoop.run; the API constructs and starts Roundtable in a supported application path, rather than only in tests. - Why this is / is not agent-owned: model-dependent action and substantive reasoning disappear with the agent actor, while retaining Onion&#39;s deterministic mechanics; the latter do not independently choose the goal&#39;s actions. - Evidence: runtime loop, tool creation and feedback, Roundtable turn/feedback. - Basis: structural. - Confidence: high for shipped model-backed action/seat loops; no claim of successful paid-provider E2E execution in this review. - Caveats: the internal loongagent dependency is not separately assessed; local app uses its installed engine and a configured model rather than a first-party foundation model.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: - State: A - Function: Roundtable reduces blocking disagreements among independent model-seat contributions to produce a coherent joint deliberative outcome or a bounded explicit divergence. - Disturbance / variety regulated: incompatible seat stances and directed rebuttals can prevent the meeting from converging. - Decisive decision or feedback right: the model-backed host chooses the first seat per round after reading the evolving transcript and outstanding disagreement; each seat can revise/rebut from shared feedback. - Decision owner: host model agent for the discretionary next-speaker selection; other seat agents own their subsequent replies. Deterministic consensus/budget computation does not inherit that discretion. - Supporting / enforcement mechanisms: shared transcript, validated seat IDs, fixed tail speaking order, agreement/rejection parsing, round/call/token ceilings and human breaker. - Closure path: conflict appears as rejected stances/rebuttals; the host reads the transcript and selects the next first speaker, seats read preceding positions on later turns; consensus or the recorded divergences determines whether to stop, continue or involve the human. - Boundary reachability: the user-facing Roundtable API creates an actual RoundtableOrchestrator, while speakingorder makes a live host model call on its first-party normal execution path. - Why this is / is not agent-owned: removal of host deliberation leaves only deterministic rotation, not the dispute-aware speaker choice; mechanical ordering and consensus calculation remain supporting machinery. The host&#39;s returned focus field is not presently forwarded as a direct seat instruction, so the positive witness is bounded to first-speaker selection plus visible transcript/replies, not a stronger agenda-control claim. - Distinct S1 units: 2–6 model-backed seats with separate replies and optional rebuttal targets. - Inter-S1 disturbance: concrete disagreeing stances/rebuttals about the shared topic, which block consensus. - Attenuating coordination relation: host selection uses the transcript and prompts priority to whoever can address the open disagreement; subsequent seats see the accumulated positions. - Feedback into subsequent S1 behaviour: next round&#39;s host prompt and seat prompts include preceding contributions, and the consensus result stops/continues the meeting. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: a real conflict representation (rejections/targeted rebuttals) is tied to disagreement-aware host choice and a next-round response path; generic message passing alone is not the credited function. - Evidence: host and seat prompts, host choice, rebuttal and consensus path, verdict implementation, rebuttal/breaker tests. - Basis: structural. - Confidence: medium; source proves a dispute-specific feedback design, not observed convergence improvement under live provider conditions. - Caveats: this is S2 in supported Roundtable mode, not in an ordinary single-agent session. The host model&#39;s optional close and focus JSON fields are not the decisive mechanical closure of a round.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S3 / regulation: - State: P - Function: parent/operator supervision of the current Roundtable&#39;s resource composition and commitments across its model-seat cells. - Disturbance / variety regulated: debate stalls, insufficient specialist coverage, divergent statements or unsatisfactory current answer distribution across seats. - Decisive decision or feedback right: the human operator chooses the meeting roster/model constraints at creation and can add a new seat, address one or all seats, and return a new directive while the meeting is underway or after the breaker. - Decision owner: the local human/operator at the application/meeting parent boundary; model host selection alone does not establish agent-owned whole-system S3. - Supporting / enforcement mechanisms: meeting status/roster/minutes, API mediation, capped seat count, inbox, event persistence, model-cost and breaker display. - Closure path: a user-added seat joins the next meeting round; a targeted message enters that seat&#39;s inbox and is delivered at its next speaking turn; post-meeting human input reopens a bounded follow-up without silently clearing prior consensus. - Boundary reachability: the shipped Roundtable UI/API connects operator messages and seat addition to the same live orchestrator and its subsequent rounds. - Why this is / is not agent-owned: the model host cannot decide to create extra provider seats or authoritatively change the operator&#39;s live constraints; these are returned human current-control decisions. Generic cancel and destructive-command approval are not separately counted as whole-system S3. - Whole-system current view: Roundtable&#39;s member roster, statements, per-seat usage, divergences and minutes are available to the user across its current operational seats. - Current-control decision scope: parent choices over team composition, targeted priorities and intervention within the bounded meeting; not an inferred global allocator across independent Onion tasks. - Evidence: Roundtable UI contract, human messages/follow-up, live seat addition, inbox return. - Basis: structural. - Confidence: medium; the positive parent claim is bounded to the current Roundtable, not whole installation-wide budgeting. - Caveats: the operator can be human and does not need to be modeled as an AI agent; no autonomous S3 resource/commitment discretion is established merely from timeouts/host ordering.\">P</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: a separate audit would have to compare ordinary operational success/claims against independent underlying reality and return findings to current control. - Disturbance / variety regulated: false reported completion, unsound execution, unobserved side effects or unverifiable model claims. - Decisive decision or feedback right: not established as a distinct first-party complementary operational audit right in the reviewed modes. - Decision owner: none evidenced for such a distinct audit; the optional safety-review model judges proposed code before execution, and the user can approve a flagged request, but neither audits a claimed completed operational outcome through another access path. - Supporting / enforcement mechanisms: code-only safety filter, Plan mode refusal, user confirmation, diff view, tests and logs. - Closure path: no first-party complementary direct-reality audit finding is wired to corrective control as a separate function. Safety-review verdicts affect the ordinary executor&#39;s pre-execution gate only. - Why this is / is not agent-owned: an isolated reviewer model is not an S3 owner without a complementary audit of operating reality; authors explicitly call it a filter, not final authority. - Evidence: review-gate invocation, code-only review, README warning. - Basis: structural. - Confidence: medium-high within the shipped runtime/reviewer/GUI paths inspected. - Caveats: no universal claim about unexamined third-party plugins or a user&#39;s own independent verification procedure.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S4 / adaptation: - State: P - Function: parent-governed prospective adaptation of the agent&#39;s future available model/tool/skill capabilities in response to demands from the external user/work environment. - Disturbance / variety regulated: new tool/provider/skill needs beyond the currently enabled local repertoire. - Decisive decision or feedback right: the working agent can formulate a reasoned future-capability change proposal, but only the legitimate local human/operator decides whether it changes the installed repertoire. - Decision owner: human parent for adoption of the future capability; no automatic agent-owned S4 closure is claimed. - Supporting / enforcement mechanisms: MetaTools proposal API, dry-run ledger diff, capability validation and versioning, MCP tool materialization and hot reload. - Closure path: user-supplied/newly encountered capability need reaches the agent prompt; agent may propose a new executor/provider/skill/MCP tool; parent applies the proposal; the next runtime constructs its tools/prompt from the revised state or hot-loaded MCP registry. - Boundary reachability: meta tools are added to the normal agent&#39;s live tool registry and afterledgerchange updates the shipped runtime, including persisted tool availability; this is not merely a developer roadmap or test fixture. - Why this is / is not agent-owned: only the parent approval changes capability. Counterfactually removing the parent leaves proposals un-applied and does not close adaptation; this is not S4=A. - External distinction: changing user tasks and available model/tool services create a capability gap that can be expressed through the tool&#39;s mandatory reason and proposal content; no autonomous external scanning is claimed. - Future / prospective distinction: requested changes alter tools/providers/skills for subsequent actions or sessions, not merely the immediate task answer. - Adaptation option generated: agent-proposed registration of an MCP tool, model-provider preset, executor or skill. - Path back into current capability / S3: approved ledger state is re-read by OnionRuntime / refreshed MCP tools and becomes an available action for subsequent S1 execution. - Evidence: default operating prompt, meta tool proposals, human apply/reload. - Basis: structural for shipped proposal/return; inferred for the external-demand-to-adaptation interpretation. - Confidence: medium-low. This is a supported parent-closed capability adaptation mode, not evidence of autonomous environmental forecasting or systematic S4 strategy. - Caveats: a generic user-chosen plugin is not S4 by itself; this positive claim is limited to the model-originated, reasoned future capability proposal and actual parent return path. No source trace establishes recurring environmental surveillance or measured adaptation effectiveness.\">P</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S5 / identity: - State: P - Function: parent-governed ultimate change to the agent&#39;s core identity and operating rules, rather than an ordinary task/tool approval. - Disturbance / variety regulated: tension between the current core behavior/policy and a desired enduring operating identity for future sessions. - Decisive decision or feedback right: human operator authoritatively accepts/rejects a model- or user-originated update to the persistent core system-prompt segment. - Decision owner: legitimate local human operator of the self-hosted agent, not the proposing agent or deterministic ledger. - Supporting / enforcement mechanisms: onionupdatesystemprompt, ChangeLedger validation/diff/version history, API confirmation and ordered system-channel prompt assembly. - Closure path: core operating-rule proposal reaches confirmation UI; operator calls apply/reject; accepted segment is persisted; composesystemprompt and OnionRuntime.composesystemprompt inject it into future model calls. - Boundary reachability: normal agent tool registry contains the prompt-update meta tool, and user-facing API applies proposals to live state read on every later task. No adjacent maintainer CI or unshipped governance actor is needed. - Why this is / is not agent-owned: model can suggest but cannot activate its own enduring identity/policy change. No separate autonomous S5 ultimate-authority mode is established. - Identity / ultimate-policy issue: the core segment begins with You are Onion and durable operating rules; changing that segment changes the identity-level instructions inherited by future tasks, distinguishable from approval of a particular shell command. - Ultimate authority in each claimed mode: only human parent mode positively established; autonomous policy proposal is not decisive authority. - Return-to-operation path: ledger apply persists the approved segment; the runtime composes the system channel from that state on the next run. - Evidence: core identity and policy, prompt-change proposal, parent application, runtime system-channel return. - Basis: structural. - Confidence: medium-high for the shipped parent closure; the grade does not imply the default agent authors its own constitutional rules. - Caveats: a generic per-tool confirmation is not counted as S5. This applies only when the human-authorized change affects the durable identity/core policy segment.\">P</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/2d4f179b0c40a972a750d2e91fbef975709c36d2/assessments/on/onion-harness.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 2d4f179b0c40a972a750d2e91fbef975709c36d2\">2d4f179 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-11-11T17:52:22+03:00\"><th scope=\"row\"><a href=\"https://github.com/sakomws/slack-agent-runtime\" target=\"_blank\" rel=\"noopener\">Slack Agent Runtime</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-11\">2026-11-11</time></td><td class=\"review-ref\"><a href=\"https://github.com/sakomws/slack-agent-runtime/tree/16bb262715b7bacb64c7466cf106063c2fdf6c93\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 16bb262715b7bacb64c7466cf106063c2fdf6c93\">16bb262 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: carry out bounded conversation/MCP actions and coding tasks based on model-selected next actions. - Disturbance / variety regulated: unstructured requests, tool replies, changing code/tests and model errors within a bounded assigned job. - Decisive decision or feedback right: choose subsequent MCP tool or coding workspace operation after observing results, and choose when to finish. - Decision owner: the first-party agent/tool and coding-worker loops supplied with an external inference model; the user selects the objective and the service bounds permissions. - Supporting / enforcement mechanisms: step budget, tool schema, WorkspaceTools, approval broker, allowlists, isolated checkout and separated publication credentials. - Closure path: Slack request or dispatched coding task → inference decision → tool execution → result injected into model conversation → next action or final result/PR artifact. - Boundary reachability: default Slack MCP path and the shipped allowlisted coding-job entrypoint invoke real first-party loops; no custom developer agent implementation is required. - Why this is / is not agent-owned: tool choice and iterative repair are model-discretionary, while approval and final publish are enforced by non-model layers. - Evidence: MCP agent loop, coding worker, tools. - Basis: implemented structural flow; no live inference run. - Confidence: high for agent-loop ownership, not for actual task success. - Caveats: the GitHub publication step uses separate credentials, and a human is required for merge; neither is credited as agent decision.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no demonstrated first-party regulation of interference among distinct autonomous S1 coding units at this recursion. - Disturbance / variety regulated: potential concurrent jobs writing to overlapping branches or projects, but no evidenced S2-specific coordination loop. - Decisive decision or feedback right: absent for inter-S1 collision resolution; admins choose work requests, while quotas/locks execute fixed limits. - Decision owner: no autonomous S2-specific coordinator identified in shipped runtime. - Supporting / enforcement mechanisms: thread state, active task tracking, policy quotas, repository allowlisting, fixed GitHub Actions dispatch. - Closure path: no first-party conflict signal → discretionary coordination → altered subsequent S1 behavior chain evidenced; isolated task guards are not this chain. - Why this is / is not agent-owned: scheduling/rate limiting does not demonstrate mediation of an inter-agent conflict. - Evidence: policy, coding dispatch, spec limitations. - Basis: bounded no-path after checking shipped dispatch, policy and coordination surfaces. - Confidence: medium-high within deployed runtime boundary. - Caveats: upstream GitHub may serialize or reject changes, but that is not first-party discretionary inter-S1 coordination.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no whole-installation discretionary present-operational supervision demonstrated. - Disturbance / variety regulated: current job failures, quota saturation and review/dispatch state are exposed but not used in a first-party whole-system control loop. - Decisive decision or feedback right: no shipped actor chooses portfolio priorities, reallocates work or changes current operational commitments from a whole-system view. - Decision owner: human administrators issue independent commands; a programmatic S3 owner is not established by their local job actions. - Supporting / enforcement mechanisms: durable Actions job-status queries, per-thread state and quotas, policy and stream cancellation. - Closure path: individual code status/review status queries return observations to requesters; no demonstrated whole-system current-view → supervisory choice → altered work portfolio path. - Why this is / is not agent-owned: current status reporting and deterministic quota enforcement are not discretionary whole-system control. - Evidence: technical specification, thread coordinator, coding plugin. - Basis: bounded source-static absence. - Confidence: medium-high for ordinary shipped modes. - Caveats: external human operations could build supervision on top; not counted without a first-party return path.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: review the correctness, reliability and security of a proposed code change through a model judgment separate from the coding worker. - Disturbance / variety regulated: builder omissions and errors that pass self-report or initial local tests. - Decisive decision or feedback right: report structured findings and select a validated severity-derived REQUESTCHANGES or APPROVE recommendation. - Decision owner: separately dispatched PullRequestReviewer model workflow; publication safety checks can downgrade its verdict. - Supporting / enforcement mechanisms: source diff extraction, exact SHA, JSON validation, check status, GitHub review publication and human merge authority. - Claim being audited: the submitted PR satisfies correctness, security and reliability requirements; reviewer does not merely summarize coding worker&#39;s completion. - Ordinary reporting path: worker summary, test report and PR diff/CI status. - Complementary access path: reviewer receives actual PR diff plus title/body with separate inference instructions, producing findings by file/line independently of worker self-report. - Independence boundary: reviewer is a distinct invocation with its own role and bounded input; same underlying provider/model or stronger institutional independence is not established. - Who acts on findings: review workflow publishes a permitted GitHub review or comment; maintainers and authors correct the change, with required checks/merge authority retained externally. - Closure path: PR head/diff → independently invoked model reviewer → validated findings/severity → GitHub review/comment → author/maintainer action before merge. - Boundary reachability: the shipped review &lt;repo&gt;#&lt;PR&gt; Slack command dispatches the review workflow; it is an opt-in built-in mode, not automatically run for every coding job. - Why this is / is not agent-owned: the reviewer generates an evaluative model judgment; deterministic review-event selection and publishing restrictions only constrain it. - Evidence: reviewer code, review plugin, review workflow architecture. - Basis: implemented separate review mode, source-static. - Confidence: medium-high in structural complementarity; review efficacy and provider independence untested. - Caveats: no automatic closed builder-fix/re-review loop proven; closure relies on normal GitHub author/maintainer feedback, so the mode&#39;s end-to-end effectiveness remains unverified.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no first-party longer-horizon scanning/adaptation decision path for the runtime&#39;s future capabilities. - Disturbance / variety regulated: prospective changes in user needs, provider/service ecosystem and platform behavior are mentioned in documents but not regulated by an operating adaptation loop. - Decisive decision or feedback right: no installed agent chooses future runtime strategy/options against external signals and returns them into current capability. - Decision owner: maintainers can revise roadmap outside the assessed runtime; no shipped S4 actor. - Supporting / enforcement mechanisms: inference web search for user tasks, roadmap, issue-oriented coding worker and spec review. - Closure path: normal user-requested coding can change external repositories; it is S1 task delivery, not foresight about this runtime&#39;s identity/capability. - Why this is / is not agent-owned: web search and document review serve immediate requests, not a prospective environment-to-adaptation loop. - Evidence: roadmap, README, technical spec. - Basis: bounded no-path for shipped first-party modes. - Confidence: medium. - Caveats: operator-maintained roadmap is not attributed to a deployed agent or parent-governed runtime S4 without return-to-operation evidence.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no evidenced first-party ultimate mission/identity decision and return loop at the runtime recursion. - Disturbance / variety regulated: role/credential access boundaries are protected, but the system&#39;s purpose/ultimate policy is not decided by the installed runtime. - Decisive decision or feedback right: no first-party agent or explicit parent policy path authoritatively revises the runtime&#39;s ultimate mission and binds later operation. - Decision owner: humans manage configuration, whitelists, deployment and merge permissions as local operational governance, not a proved S5 identity-mode closure. - Supporting / enforcement mechanisms: admin IDs, repository allowlists, MCP approval, credentials, model choice and separated privileged publication stages. - Closure path: local policy configuration gates requests; it does not demonstrate an ultimate-policy decision circuit, nor make approval requests S5 by default. - Why this is / is not agent-owned: permission checks and human approvals enforce task scope without selecting a durable system identity. - Evidence: policy module, technical spec, approval broker. - Basis: bounded absence, not a judgment on the human maintainer organization&#39;s actual policy. - Confidence: medium; no runtime identity decision path identified. - Caveats: configuration policy can reflect human values; this alone does not prove the required ultimate-policy function.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/2c490e2b9da35239ab17f1fd10a4f48c686b3367/assessments/sl/slack-agent-runtime.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 2c490e2b9da35239ab17f1fd10a4f48c686b3367\">2c490e2 &#8599;</a></td></tr>"];
